            descriptionLongue = "Natürlicher Citrin ist selten; der Großteil der auf dem Markt erhältlichen Steine stammt aus erhitztem Amethyst oder Rauchquarz, wodurch sich die Farbe in ein stabiles Goldgelb verwandelt. Als Geburtsstein des Monats November wird er mit Überfluss assoziiert.",
            particularites = "Sehr erschwinglich und reichlich vorhanden; wenige bis keine sichtbaren Einschlüsse.",
            inclusions = "Meist sehr rein; kann seltene Negativkristalle oder von erhitztem Amethyst geerbte chevronförmige Wachstumsschatten zeigen.",
            lithotherapie = "Als Stein des Überflusses bekannt, soll Citrin Selbstvertrauen, Lebensfreude und materiellen Erfolg fördern."
        ),
        "heliodore" to GemTranslation(
            nom = "Heliodor",
            descriptionCourte = "Goldener Verwandter von Smaragd und Aquamarin.",
            descriptionLongue = "Heliodor, dessen Name auf Griechisch „Geschenk der Sonne“ bedeutet, ist die gelbe bis gelbgrüne Varietät des Berylls. Weniger bekannt als seine Verwandten Smaragd und Aquamarin, besticht er durch seine leuchtende Klarheit.",
            particularites = "In der Regel sehr rein, wenige Einschlüsse.",
            inclusions = "Hohlkanäle parallel zur Kristallachse und seltene Flüssigkeitseinschlüsse, wie bei anderen Beryllen.",
            lithotherapie = "Heliodor wird mit Freude und Großzügigkeit assoziiert und soll Aufgeschlossenheit und geistige Klarheit fördern."
        ),
        "chrysoberyl" to GemTranslation(
            nom = "Chrysoberyll",
            descriptionCourte = "Hohe Härte, Verwandter des Alexandrits.",
            descriptionLongue = "Mit einer Härte von 8,5 zählt der gelbgrüne Chrysoberyll nach Korund und Diamant zu den widerstandsfähigsten Edelsteinen. Seine farbwechselnde Varietät bringt den Alexandrit hervor, seine schillernde Varietät den Katzenauge-Effekt.",
            particularites = "Hervorragende Abnutzungsbeständigkeit, ideal für den täglichen Gebrauch.",
            inclusions = "Kann charakteristische zyklische Zwillinge in Form eines dreistrahligen Sterns sowie feine Flüssigkeitseinschlüsse zeigen.",
            lithotherapie = "Chrysoberyll soll die Urteilsfähigkeit fördern und Wohlstand in persönlichen wie beruflichen Angelegenheiten anziehen."
        ),
        "oeil-de-tigre" to GemTranslation(
            nom = "Tigerauge",
            descriptionCourte = "Goldenes Schillern in einem beweglichen Lichtband.",
            descriptionLongue = "Das Tigerauge verdankt sein goldenes Schillern Krokydolith-Fasern (einer Asbestvarietät), die zu Quarz pseudomorphosiert wurden. Als Cabochon geschliffen, zeigt es ein bewegliches Lichtband, das sich mit dem einfallenden Licht verschiebt.",
            particularites = "Wird stets als Cabochon geschliffen, um das Schillern (Katzenaugeneffekt) sichtbar zu machen.",
            lithotherapie = "Als Stein des Schutzes und des Selbstvertrauens wird das Tigerauge häufig genutzt, um Entschlossenheit zu stärken und sich vor negativen Einflüssen zu schützen."
        ),
        "scapolite" to GemTranslation(
            nom = "Skapolith",
            descriptionCourte = "Wenig bekannt, von Honiggelb bis Violett.",
            descriptionLongue = "Skapolith bildet eine der breiten Öffentlichkeit wenig bekannte Mineralreihe, die zu durchscheinenden honiggelben bis rosafarbenen Edelsteinen geschliffen wird. Manche Kristalle aus Myanmar zeigen einen Schillereffekt oder eine orangefarbene UV-Fluoreszenz.",
            particularites = "Manche birmanischen Steine zeigen einen ausgeprägten Katzenaugeneffekt.",
            inclusions = "Parallele faserige Einschlüsse, die bei manchen burmesischen Steinen einen Chatoyance-Effekt (Katzenauge) erzeugen können.",
            lithotherapie = "Skapolith wird mit persönlicher Disziplin und Motivation assoziiert, hilfreich bei der Umsetzung eigener Vorhaben."
        ),
        "malachite" to GemTranslation(
            nom = "Malachit",
            descriptionCourte = "Das ikonische Kupfergrün in konzentrischen Bändern.",
            descriptionLongue = "Malachit bildet traubenförmige (botryoidale) Massen mit konzentrischen Bändern in Hell- bis Dunkelgrün, gefärbt durch Kupfer. Bereits im alten Ägypten als Pigment und Schmuckstein verwendet, ziert er sowohl Schmuck als auch Mobiliar (Säulen des Kreml).",
            particularites = "Stets als Cabochon oder poliertes Objekt geschliffen; wegen seiner Weichheit und Opazität niemals facettiert.",
            lithotherapie = "Als Stein der Transformation soll Malachit negative Energien aufnehmen und Lebensveränderungen sanft begleiten."
        ),
        "dioptase" to GemTranslation(
            nom = "Dioptas",
            descriptionCourte = "Ein intensives Smaragdgrün, das mit dem Smaragd selbst konkurriert.",
            descriptionLongue = "Dioptas bildet kleine Kristalle in einem so intensiven Smaragdgrün, dass sie optisch mit dem echten Smaragd konkurrieren, doch seine große Zerbrechlichkeit und vollkommene Spaltbarkeit machen ihn fast ausschließlich zu einem Sammlerstein.",
            particularites = "Vollkommene Spaltbarkeit und hohe Zerbrechlichkeit: Ein facettierter Schliff ist eine lapidare Meisterleistung, die nur selten gewagt wird.",
            inclusions = "Kristalle oft verbunden mit Dolomit oder Calcit aus dem Wirtsgestein; wegen der vollkommenen Spaltbarkeit selten facettiert.",
            lithotherapie = "Dioptas wird mit tiefgreifender emotionaler Heilung assoziiert und soll Vergebung sowie die Linderung von Herzenswunden fördern."
        ),
        "libethenite" to GemTranslation(
            nom = "Libethenit",
            descriptionCourte = "Ein oliv- bis dunkelgrünes wasserhaltiges Kupferphosphat, ein seltener Sammlermineral.",
            descriptionLongue = "Libethenit bildet kleine prismatische oder pyramidale Kristalle in oliv- bis dunkelgrüner, fast schwarzer Farbe, die zu drusenartigen Aggregaten auf oxidierter Gangart zusammenwachsen. Er wurde im 19. Jahrhundert in Ľubietová (früher Libethen) in der Slowakei entdeckt, wonach er benannt ist, und entsteht in der Oxidationszone von Kupferlagerstätten, oft zusammen mit Malachit und anderen Kupferphosphaten. Ein facettierter Schliff bleibt eine Ausnahme: Er ist vor allem ein Sammlermineral.",
            particularites = "Sekundäres Mineral der Verwitterungszone von Kupferlagerstätten, oft mit Malachit und anderen Kupferphosphaten vergesellschaftet; seine Seltenheit macht ihn fast ausschließlich zu einem Stück für Mineraliensammler.",
            lithotherapie = "Libethenit wird in der Kristallheilkunde manchmal mit Erdung und Regeneration in Verbindung gebracht, in der Tradition der als energetisierend geltenden Kupferminerale."
        ),
        "amazonite" to GemTranslation(
            nom = "Amazonit",
            descriptionCourte = "Ein opakes Blaugrün mit weißen Streifen, trotz seines Namens ohne Bezug zum Amazonas.",
            descriptionLongue = "Amazonit ist eine opake blaugrüne Varietät des Mikroklins mit weißen Aderungen. Sein Name erinnert an den Amazonas-Fluss, obwohl dort nie ein historisches Vorkommen bestätigt wurde – eines der bleibenden Rätsel der Mineralogie.",
            particularites = "Wird wegen seiner Opazität stets als Cabochon geschliffen; empfindlich gegenüber Stößen entlang seiner Spaltebenen.",
            inclusions = "Polysynthetische Zwillingsstruktur, verantwortlich für das charakteristische gestreifte blaugrüne Erscheinungsbild, mitunter durchzogen von feinen weißen Quarz- oder Albitadern.",
            lithotherapie = "Als beruhigender Stein soll Amazonit Stress lindern und eine aufrichtige Kommunikation mit anderen erleichtern."
        ),
        "chrysoprase" to GemTranslation(
            nom = "Chrysopras",
            descriptionCourte = "Das kräftigste Apfelgrün der Chalcedon-Familie.",
            descriptionLongue = "Chrysopras ist die Chalcedon-Varietät mit dem intensivsten Apfelgrün, gefärbt durch Nickelspuren. Bereits in der Antike geschätzt, erlebte er im 18. Jahrhundert eine erneute Blüte, insbesondere im Mobiliar Friedrichs des Großen von Preußen.",
            particularites = "Die Farbe kann bei anhaltender Austrocknung oder starker Hitze verblassen; hält sich am besten bei leichter Feuchtigkeit.",
            inclusions = "Grüne Färbung durch in der mikrokristallinen Kieselsäure verteiltes Nickel; kann feine weißliche Aderungen zeigen.",
            lithotherapie = "Chrysopras wird traditionell mit Hoffnung und Optimismus assoziiert und öffnet das Herz für neue Perspektiven."
        ),
        "beryl-vert" to GemTranslation(
            nom = "Grüner Beryll",
            descriptionCourte = "Das „gewöhnliche“ Grün des Berylls, ohne das Chrom, das ihn zum Smaragd machen würde.",
            descriptionLongue = "Gefärbt durch Eisen statt durch Chrom oder Vanadium, hat der grüne Beryll gemmologisch streng genommen kein Anrecht auf die Bezeichnung „Smaragd“, bietet aber saubere, leuchtende Steine zu einem deutlich erschwinglicheren Preis.",
            particularites = "Wird vom Smaragd mittels Spektroskop unterschieden: Fehlen der Chrom-/Vanadium-Absorptionslinien.",
            inclusions = "Einschlüsse in Form paralleler Hohlkanäle und gelegentliche akzessorische Mineralkristalle; meist mit bloßem Auge sehr rein.",
            lithotherapie = "Grüner Beryll soll emotionales Gleichgewicht und Erneuerung bringen und helfen, nach einer schwierigen Phase einen neuen Abschnitt zu beginnen."
        ),
        "sillimanite" to GemTranslation(
            nom = "Sillimanit",
            descriptionCourte = "Eine wenig bekannte Verwandte von Andalusit und Disthen, mitunter mit Katzenaugeneffekt.",
            descriptionLongue = "Als Polymorph von Andalusit und Cyanit (gleiche Formel, unterschiedliche Kristallstruktur) tritt Sillimanit in Blaugrün- bis Brauntönen auf, teils mit einem in Cabochons begehrten Schillereffekt.",
            particularites = "Kann bei senkrecht zu den Fasern geschliffenen Cabochons einen sehr deutlichen Katzenaugeneffekt zeigen.",
            inclusions = "Faserige Einschlüsse, die bei Cabochon-Steinen einen Chatoyance-Effekt (Katzenauge) erzeugen können.",
            lithotherapie = "Sillimanit wird mit geistiger Klarheit assoziiert, eine Stütze, um Gedanken und Prioritäten zu ordnen."
        ),
        "seraphinite" to GemTranslation(
            nom = "Seraphinit",
            descriptionCourte = "Ein tiefes Grün, durchzogen von seidigen silbrigen Federmustern.",
            descriptionLongue = "Seraphinit, der Handelsname einer Klinochlor-Varietät, zeigt federartige silbrige Muster auf dunkelgrünem Grund, die an Engelsflügel erinnern – daher sein Name. Er wird stets als polierter Cabochon verarbeitet, um dieses seidige Schillern sichtbar zu machen.",
            particularites = "Extrem weich: sollte Schmuckstücken vorbehalten bleiben, die kaum Stößen ausgesetzt sind (Anhänger, Ohrringe).",
            lithotherapie = "Als Stein der tiefen Heilung soll Seraphinit helfen, sich von wiederkehrenden Mustern zu befreien und einen inneren Neuanfang einzuleiten."
        ),
        "grenat-grossulaire" to GemTranslation(
            nom = "Grossular-Granat",
            descriptionCourte = "Der grüne bis gelbgrüne Granat, farbschwache Verwandte von Tsavorit und Hessonit.",
            descriptionLongue = "Grossular reicht von farblos bis intensiv grün über gelbgrün („Mali-Granat“), je nach vorhandenen Eisen-, Mangan- oder Vanadiumspuren – Tsavorit und Hessonit sind seine bekanntesten Varietäten.",
            particularites = "Die farbenreichste aller Granatfamilien, von farblos bis zum tiefen Grün des Tsavorits.",
            inclusions = "Je nach Lagerstätte unterschiedliche akzessorische Kristalle, mit Spannungshöfen um kleine eingeschlossene Kristalle.",
            lithotherapie = "Der Grossular-Granat wird mit Überfluss und Vitalität assoziiert und ist eine Stütze in Phasen des persönlichen Wiederaufbaus."
        ),
        "diopside" to GemTranslation(
            nom = "Chromdiopsid",
            descriptionCourte = "Ein tiefes Tannengrün durch Chrom, verwandt mit dem Demantoid-Granat.",
            descriptionLongue = "Chromdiopsid verdankt sein intensives, dem Smaragd nahekommendes Grün Chromspuren. In denselben Lagerstätten wie Diamanten (Kimberliten) vorkommend, dient er Prospektoren mitunter als Indikatormineral.",
            particularites = "Geringe Härte, die im Schmuckgebrauch Vorsicht erfordert; manche Steine zeigen Asterismus oder einen Katzenaugeneffekt.",
            inclusions = "Feine schwarze nadelförmige Einschlüsse (Magnetit oder Chromit) und unter der Lupe mitunter sichtbare akzessorische Kristalle.",
            lithotherapie = "Chromdiopsid soll die Verbindung zur Natur und das alltägliche emotionale Gleichgewicht fördern."
        ),
        "jade-nephrite" to GemTranslation(
            nom = "Nephrit-Jade",
            descriptionCourte = "Die historische Jade aus China und Neuseeland, zu unterscheiden von Jadeit.",
            descriptionLongue = "Vor der Entdeckung des birmanischen Jadeits im 18. Jahrhundert bestand alle im kaiserlichen China, in Neuseeland (Māori-Pounamu) und im präkolumbischen Amerika bearbeitete Jade aus Nephrit – einem Amphibol mit mikroskopisch feiner Faserverfilzung, die ihm außergewöhnliche Zähigkeit verleiht.",
            particularites = "Die filzartige Faserstruktur macht ihn trotz einer etwas geringeren Härte stoßfester als Jadeit.",
            lithotherapie = "Als Stein der Weisheit und Harmonie seit dem chinesischen Altertum soll Nephrit-Jade Gelassenheit, Schutz und Langlebigkeit bringen."
        ),
        "maw-sit-sit" to GemTranslation(
            nom = "Maw-Sit-Sit",
            descriptionCourte = "Ein leuchtendes Grün mit schwarzen Adern, benannt nach einem birmanischen Dorf.",
            descriptionLongue = "Maw-Sit-Sit, benannt nach dem birmanischen Dorf, in dem es 1963 entdeckt wurde, ist ein überwiegend aus Jadeit und Kosmochlor (einem chromhaltigen Pyroxen) bestehendes Gestein mit leuchtendem Grün, durchzogen von schwarzen Adern, und in Asien sehr geschätzt.",
            particularites = "Bis heute weltweit einzige bekannte Fundstätte, in der Nähe der Jadeitminen von Hpakant gelegen.",
            lithotherapie = "Maw-Sit-Sit wird mit Erneuerung und dem Fluss positiver Energie in Übergangsphasen assoziiert."
        ),
        "tourmaline-chrome" to GemTranslation(
            nom = "Chromturmalin",
            descriptionCourte = "Ein tiefes, gesättigtes Grün durch Chrom und Vanadium, verschieden vom „klassischen“ Grün.",
            descriptionLongue = "Gefärbt durch Chrom und Vanadium statt durch Eisen, zeigt Chromturmalin ein gesättigteres und tieferes Grün als gewöhnlicher grüner Turmalin, mit einem ausgeprägten Dichroismus zwischen Grün und Braungrün je nach Betrachtungswinkel.",
            particularites = "Ausgeprägter Dichroismus: Die Ausrichtung der Tafel ist entscheidend, um den gesättigtsten Farbton sichtbar zu machen.",
            inclusions = "Feine Trichite und gelegentliche kristalline Einschlüsse, vergleichbar mit anderen grünen Turmalinen.",
            lithotherapie = "Chromturmalin soll die Vitalität anregen und zugleich die Öffnung des Herzens sowie Mitgefühl fördern."
        ),
        "saphir-vert" to GemTranslation(
            nom = "Grüner Saphir",
            descriptionCourte = "Ein zurückhaltendes, oft dichroitisches Grün, die erschwinglichste Farbe des Korunds.",
            descriptionLongue = "Gefärbt durch Eisen, zeigt der grüne Saphir oft einen deutlichen Dichroismus (Grün und Gelbgrün je nach Winkel), ein Erkennungsmerkmal, das ihn von anderen grünen Edelsteinen unterscheidet. In der Regel ist es die erschwinglichste Farbe unter den Saphiren.",
            particularites = "Ausgeprägter Dichroismus zwischen Grün und Gelbgrün je nach Betrachtungsachse, nützlich zur Identifikation.",
            inclusions = "Charakteristische Farbzonierung in parallelen Bändern, feine Rutilseide und akzessorische Mineralkristalle, typisch für Korund.",
            lithotherapie = "Grüner Saphir wird mit innerem Gleichgewicht und Weisheit assoziiert, eine Stütze, um Abstand zu gewinnen."
        ),
        "emeraude" to GemTranslation(
            nom = "Smaragd",
            descriptionCourte = "Das begehrteste Grün der Schmuckkunst.",
            descriptionLongue = "Der Smaragd verdankt sein tiefes Grün Chrom und/oder Vanadium. Seine natürlichen Einschlüsse, die als „Jardin“ bezeichnet werden, zeugen von seiner Echtheit und werden in der Regel durch eine Behandlung mit Zedernöl stabilisiert – eine auf dem Markt akzeptierte und erwartete Praxis.",
            particularites = "Nahezu systematische Ölbehandlung; empfindlicher Stein, der besondere Vorsicht erfordert.",
            inclusions = "„Jardin\": charakteristische mehrphasige Einschlüsse (Flüssigkeit, Gas, Kristall), Pyritkristalle (Kolumbien), Aktinolith oder Glimmer; natürliche Risse werden typischerweise mit Zedernöl aufgefüllt.",
            lithotherapie = "Als Stein der Liebe und der Weisheit gilt der Smaragd traditionell als beruhigend für emotionale Spannungen und als förderlich für Treue und Harmonie in Beziehungen."
        ),
        "peridot" to GemTranslation(
            nom = "Peridot",
            descriptionCourte = "Leuchtendes Olivgrün, niemals behandelt.",
            descriptionLongue = "Der Peridot ist eine der wenigen Edelsteine, die aus einer einzigen Mineralspezies (Olivin) bestehen, und wird niemals behandelt. Seine starke Doppelbrechung lässt die Kantenverdopplung mitunter mit bloßem Auge durch die Tafel des Steins erkennen.",
            particularites = "Mit bloßem Auge sichtbare Doppelbrechung; manche Steine stammen aus Meteoriten (Pallasiten).",
            inclusions = "Häufige schwarze Chromit-Einschlüsse, umgeben von einer als „Seerosenblatt\" bezeichneten Spannungsscheibe, zusammen mit feinen Biotit-Glimmerkristallen.",
            lithotherapie = "Der Peridot wird mit allgemeinem Wohlbefinden und Loslassen assoziiert und soll dabei helfen, sich von Groll und Ressentiments zu befreien."
        ),
        "tsavorite" to GemTranslation(
            nom = "Tsavorit",
            descriptionCourte = "Dauerhafte, unbehandelte Alternative zum Smaragd.",
            descriptionLongue = "Der 1967 in der Nähe des Tsavo-Nationalparks in Kenia entdeckte Tsavorit verdankt seine grüne Farbe Vanadium und Chrom. Da er stets unbehandelt bleibt, bietet er oft einen höheren Glanz und eine größere Reinheit als der Smaragd.",
            particularites = "Niemals behandelt; begrenzte Vorkommen machen große Steine sehr selten.",
            inclusions = "Feine Fasern und akzessorische Kristalle (oft Magnetit oder Graphit); ostafrikanische Steine sind meist von guter Reinheit.",
            lithotherapie = "Der Tsavorit soll die Vitalität und das Selbstvertrauen stärken und dabei unterstützen, Herausforderungen mit Energie anzugehen."
        ),
        "jade-jadeite" to GemTranslation(
            nom = "Jade (Jadeit)",
            descriptionCourte = "Der heilige Stein der chinesischen Kultur.",
            descriptionLongue = "Jadeit bildet ein mikrokristallines Aggregat von außergewöhnlicher Zähigkeit, wodurch er sich vom Nephrit unterscheidet, dem anderen als „Jade“ bezeichneten Mineral. In China als „Stein des Himmels“ verehrt, symbolisiert er Reinheit und Tugend.",
            particularites = "Trotz mäßiger Härte extrem zäh; die „kaiserliche“ Qualität mit durchscheinendem Grün ist äußerst selten.",
            lithotherapie = "Jadeit-Jade soll Glück und Schutz bringen und zugleich die Harmonie in Beziehungen sowie die innere Gelassenheit fördern."
        ),
        "tourmaline-verte" to GemTranslation(
            nom = "Grüner Turmalin (Verdelith)",
            descriptionCourte = "Grün, gefärbt durch Eisen oder Chrom.",
            descriptionLongue = "Der Verdelith deckt je nach Spuren von Eisen, Chrom oder Vanadium ein breites Spektrum an Grüntönen ab, von hellem Minzgrün bis zu tiefem Waldgrün. Sein starker Pleochroismus kann seinen Farbton je nach Schliffwinkel spürbar verändern.",
            particularites = "Starke Doppelbrechung; Schleifer richten den Stein aus, um die Farbe zu optimieren.",
            inclusions = "Wattefaden-Trichite, Hohlkanäle parallel zur c-Achse und mitunter sichtbare Farbzonierung.",
            lithotherapie = "Der grüne Turmalin wird mit emotionalem Gleichgewicht und Regeneration in Verbindung gebracht, eine Unterstützung nach Phasen seelischer Erschöpfung."
        ),
        "demantoide" to GemTranslation(
            nom = "Demantoid-Granat",
            descriptionCourte = "Höhere Dispersion als der Diamant.",
            descriptionLongue = "Der Demantoid ist die begehrteste grüne Varietät des Andradit-Granats und wird durch Chrom gefärbt. Seine Dispersion (das „Feuer“) übertrifft die des Diamanten, und seine faserigen „Pferdeschweif“-Einschlüsse (Byssolith) gelten bei Sammlern als geschätztes Echtheitsmerkmal.",
            particularites = "Außergewöhnliche optische Dispersion; „Pferdeschweif“-Einschlüsse sind charakteristisch für Steine aus dem Ural.",
            inclusions = "Radial angeordnete faserige „Pferdeschweif\"-Einschlüsse (Byssolith), das Erkennungsmerkmal der Uralsteine und ein sehr geschätztes Echtheitszeichen.",
            lithotherapie = "Der Demantoid-Granat soll Wohlstand anziehen und die Lebensfreude im Alltag neu entfachen."
        ),
        "uvarovite" to GemTranslation(
            nom = "Uwarowit-Granat",
            descriptionCourte = "Smaragdgrün in Drusen aus Mikrokristallen.",
            descriptionLongue = "Uwarowit bildet fast immer winzige Kristalle in Drusen, die nur selten groß genug für einen Facettenschliff sind. Sein intensives, durch Chrom bedingtes Smaragdgrün macht ihn dennoch zu einem begehrten Sammlerstück im Rohzustand.",
            particularites = "Kristalle sind fast immer zu klein für den Facettenschliff; wird roh in Drusenform gesammelt.",
            inclusions = "Tritt meist als winzige Druse-Kristalle auf; innere Einschlüsse sind aufgrund der geringen Größe wenig dokumentiert.",
            lithotherapie = "Uwarowit wird mit innerer Beruhigung und einer stärkeren Verbindung zur umgebenden Natur assoziiert."
        ),
        "vesuvianite" to GemTranslation(
            nom = "Vesuvian (Idokras)",
            descriptionCourte = "Entdeckt an den Hängen des Vesuvs.",
            descriptionLongue = "Erstmals auf den Lavaströmen des Vesuvs beschrieben, zeigt der Vesuvian (oder Idokras) Farbtöne von Olivgrün bis Flaschengrün. Seine massive, kompakte Varietät, der Californit, wird mitunter als Jade-Ersatz verwendet.",
            particularites = "Die massive Varietät Californit kann Nephrit-Jade nachahmen.",
            inclusions = "Je nach Lagerstätte feine körnige Einschlüsse und akzessorische Kristalle, oft mit leicht trüber innerer Struktur.",
            lithotherapie = "Der Vesuvian soll dazu ermutigen, über sich selbst hinauszuwachsen, und die Kreativität bei persönlichen Projekten anregen."
        ),
        "prehnite" to GemTranslation(
            nom = "Prehnit",
            descriptionCourte = "Durchscheinendes Pistaziengrün.",
            descriptionLongue = "Als erstes Mineral überhaupt nach einer Person benannt (Oberst von Prehn), bildet Prehnit traubenförmige Aggregate in Pistazien- bis Gelbgrün, die als Cabochon oder – wenn der Kristall es zulässt – gelegentlich facettiert geschliffen werden.",
            particularites = "Häufig als Cabochon geschliffen; wird mitunter mit Chrysopras verwechselt.",
            inclusions = "Charakteristische faserig-radialstrahlige Struktur mit leicht chatoyantem Erscheinungsbild, mitunter mit nadelförmigen Einschlüssen von grünem Epidot.",
            lithotherapie = "Prehnit wird mit Gelassenheit und dem Hören auf die eigene Intuition assoziiert, eine Unterstützung für die Meditation."
        ),
        "chrysocolle" to GemTranslation(
            nom = "Chrysokoll",
            descriptionCourte = "Kupferfarbenes Blaugrün, oft in Quarzmatrix.",
            descriptionLongue = "Chrysokoll wird durch Kupfer gefärbt und ist nur selten hart genug, um allein geschliffen zu werden: Meist wird er in eine Quarzmatrix eingebettet und stabilisiert („Chrysokoll in Quarz“), was ihm die für die Schmuckherstellung nötige Härte verleiht, während seine türkis- bis tiefgrünen Farbtöne erhalten bleiben.",
            particularites = "In reiner Form zu weich; für die Schmuckherstellung mit Quarz durchtränkt.",
            inclusions = "Oft verbunden mit teilweiser Verkieselung (Chrysokoll-in-Quarz), mit Einschlüssen von gediegenem Kupfer oder Malachit je nach Lagerstätte.",
            lithotherapie = "Chrysokoll soll den Selbstausdruck erleichtern und emotionale Spannungen im Zusammenhang mit Kommunikation lindern."
        ),
        "variscite" to GemTranslation(
            nom = "Variszit",
            descriptionCourte = "Durchscheinendes Apfelgrün, verwandt mit dem Türkis.",
            descriptionLongue = "Als chemisch dem Türkis nahestehendes Aluminiumphosphat zeigt Variszit ein geädertes Apfel- bis Smaragdgrün, das häufig von feinen weißen Crandallit-Adern durchzogen ist. Als Cabochon geschliffen, bleibt er auf dem Markt ein Nischenprodukt.",
            particularites = "Wird häufig mit Türkis verwechselt; stets als Cabochon geschliffen.",
            lithotherapie = "Variszit wird mit emotionalem Gleichgewicht assoziiert und soll ein Gefühl von Trost und innerer Sicherheit vermitteln."
        ),
        "serpentine" to GemTranslation(
            nom = "Serpentin (Bowenit)",
            descriptionCourte = "Erschwingliche Alternative zur Jade.",
            descriptionLongue = "Bowenit, eine kompakte und harte Serpentin-Varietät, wird seit der Antike in Neuseeland (Pounamu) und China als Ersatz für Nephrit-Jade verwendet. Sein durchscheinendes Grün und seine Zähigkeit machen ihn zu einem geschätzten Schmuckstein.",
            particularites = "Die härtere und durchscheinende Varietät Bowenit ist in der Schmuckherstellung am begehrtesten.",
            lithotherapie = "Serpentin soll Regeneration und Erdung fördern, eine Unterstützung in Phasen des persönlichen Neuaufbaus."
        ),
        "grandidierite" to GemTranslation(
            nom = "Grandidierit",
            descriptionCourte = "Einer der seltensten Edelsteine der Welt, pleochroitisches Blaugrün.",
            descriptionLongue = "1902 auf Madagaskar entdeckt und zu Ehren des Forschungsreisenden Alfred Grandidier benannt, sind vom Grandidierit weltweit nur eine Handvoll transparenter, schleiffähiger Kristalle bekannt. Sein starker Pleochroismus lässt seine Farbe je nach Betrachtungswinkel von Blaugrün zu Weiß wechseln.",
            particularites = "Weniger als zwanzig transparente geschliffene Steine sind weltweit verzeichnet.",
            inclusions = "Eine sehr seltene Spezies; innere Einschlüsse wenig dokumentiert, da bekannte facettierte Steine klein und bei Sammlern sehr begehrt sind.",
            lithotherapie = "Als seltenes und kostbares Mineral wird der Grandidierit in der Lithotherapie mit tiefer Gelassenheit und einer Öffnung des Herzens assoziiert."
        ),
        "azurite" to GemTranslation(
            nom = "Azurit",
            descriptionCourte = "Das tiefe Blau des Kupfers, oft verwachsen mit Malachit.",
            descriptionLongue = "Azurit bildet Kristalle und Massen von intensivem, tiefem Blau, gefärbt durch Kupfer. Da er langfristig instabil ist (er kann sich bei Kontakt mit Feuchtigkeit in Malachit umwandeln), wird er vor allem zu Cabochons oder Dekorationsobjekten verarbeitet, häufig in Verbindung mit grünem Malachit.",
            particularites = "Kann sich allmählich in Malachit umwandeln (Pseudomorphose); vor Feuchtigkeit und direktem Licht zu schützen.",
            lithotherapie = "Azurit soll die Intuition und geistige Klarheit fördern, eine Unterstützung beim Nachdenken und Treffen von Entscheidungen."
        ),
        "sodalite" to GemTranslation(
            nom = "Sodalith",
            descriptionCourte = "Ein tiefes, weiß geädertes Blau, oft mit Lapislazuli verwechselt.",
            descriptionLongue = "Sodalith zeigt ein königsblaues Blau, geadert von weißem Calcit, das dem Lapislazuli ähnelt, jedoch ohne dessen goldene Pyrit-Einschlüsse. Seit seiner Entdeckung in Grönland im 19. Jahrhundert wird er für Cabochons, Einlegearbeiten und Dekorationsobjekte verwendet.",
            particularites = "Unterscheidet sich vom Lapislazuli durch das Fehlen goldener Pyrit-Einschlüsse und eine geringere Dichte.",
            lithotherapie = "Sodalith wird mit klarer Kommunikation und Logik assoziiert und soll zugleich geistige Ängste lindern."
        ),
        "larimar" to GemTranslation(
            nom = "Larimar",
            descriptionCourte = "Das einzigartige Karibikblau eines Pektolith, der nur auf einer einzigen Insel gefunden wird.",
            descriptionLongue = "Larimar ist eine Pektolith-Varietät in Türkis- bis Himmelblau, die an die Gewässer der Karibik erinnert; seine Farbe stammt von Kupferspuren. Ein weltweit nahezu einzigartiges Vorkommen in der Dominikanischen Republik macht ihn zu einem geografisch exklusiven Edelstein.",
            particularites = "Nahezu exklusives Vorkommen; der Name setzt sich aus „Larissa“ (Tochter des Entdeckers) und „mar“ (spanisch für Meer) zusammen.",
            lithotherapie = "Als Stein der Gelassenheit soll Larimar Stress lindern und eine aufrichtige, aus dem Herzen kommende Kommunikation erleichtern."
        ),
        "lazulite" to GemTranslation(
            nom = "Lazulith",
            descriptionCourte = "Ein tiefes Blau, das trotz der Namensähnlichkeit nicht mit Lapislazuli zu verwechseln ist.",
            descriptionLongue = "Lazulith bildet Kristalle von azur- bis intensivem Indigoblau; der Name klingt zwar ähnlich wie Lapislazuli, doch chemisch und mineralogisch besteht keinerlei Verwandtschaft. In facettierfähiger Qualität selten, wird er vor allem als Mineralienstück gesammelt.",
            particularites = "Trotz der Namensähnlichkeit nicht mit Lazurit (Bestandteil des Lapislazuli) zu verwechseln.",
            inclusions = "Je nach Lagerstätte faserige Einschlüsse und akzessorische Kristalle; wegen der Seltenheit in Edelsteinqualität selten geschliffen.",
            lithotherapie = "Lazulith wird mit Introspektion und geistiger Ruhe assoziiert, eine Unterstützung für Meditation und innere Reflexion."
        ),
        "hauyne" to GemTranslation(
            nom = "Hauyn",
            descriptionCourte = "Ein intensives Ultramarinblau in vulkanischem Gestein, ein seltener Verwandter des Lapislazuli.",
            descriptionLongue = "Der nach dem Kristallografen René Just Haüy benannte Hauyn zeigt ein tiefes Ultramarinblau, ähnlich dem Lazurit des Lapislazuli, kommt jedoch in isolierten Kristallen in vulkanischen Laven vor und ist nur äußerst selten facettierbar.",
            particularites = "Edelsteinkristalle sind selten größer als wenige Millimeter; der Facettenschliff ist eine Ausnahme.",
            inclusions = "Je nach vulkanischer Herkunftslagerstätte seltene kristalline Einschlüsse; ein in facettierbarer Qualität extrem seltener Stein.",
            lithotherapie = "Der seltene Hauyn wird in der Lithotherapie mit authentischem Selbstausdruck und dem Vertrauen in die eigene Stimme assoziiert."
        ),
        "cavansite" to GemTranslation(
            nom = "Cavansit",
            descriptionCourte = "Ein elektrisches Türkisblau in kristallinen Rosetten, ein Star der Mineralienbörsen.",
            descriptionLongue = "Cavansit bildet Rosetten aus leuchtend türkisblauen Kristallen, die Basaltgeoden auskleiden. Er wird vor allem von Mineraliensammlern wegen seines glasigen Glanzes und seiner satten Farbe geschätzt und aufgrund der geringen Kristallgröße nur selten geschliffen.",
            particularites = "Nahezu exklusives Vorkommen in den Deccan-Basalten Indiens; wird praktisch nie facettiert.",
            inclusions = "Tritt meist als radialstrahlige sphärolithische Aggregate auf; als einzelner reiner Stein selten facettiert.",
            lithotherapie = "Cavansit soll das spirituelle Erwachen und geistige Klarheit in Phasen des Hinterfragens fördern."
        ),
        "celestite" to GemTranslation(
            nom = "Coelestin",
            descriptionCourte = "Ein zartes Himmelblau, ein weiches Mineral, das vor allem als Geode gesammelt wird.",
            descriptionLongue = "Coelestin bildet tafelige Kristalle von zartem, an den Himmel erinnerndem Blau, daher sein Name. Seine extreme Weichheit macht ihn fast ausschließlich zu einem Objekt für Mineraliensammlungen und dekorative Geoden statt für die Schmuckherstellung.",
            particularites = "Zu weich und spaltbar für die Schmuckverarbeitung; im Wesentlichen ein Sammler- und Dekorationsstein.",
            inclusions = "Oft tafelige prismatische Kristalle und feine Flüssigkeitseinschlüsse; wegen ihrer Zerbrechlichkeit (vollkommene Spaltbarkeit, geringe Härte) selten facettiert.",
            lithotherapie = "Als Stein tiefer Beruhigung soll Coelestin einen ruhigen Schlaf fördern und unruhige Gedanken besänftigen."
        ),
        "euclase" to GemTranslation(
            nom = "Euklas",
            descriptionCourte = "Ein kristallines Blaugrün von bemerkenswerter Transparenz, gefährlich zerbrechlich.",
            descriptionLongue = "Euklas („gut spaltbar“ im Griechischen) verdankt seinen Namen seiner perfekten Spaltbarkeit, die ihn beim Schleifen äußerst heikel macht. Seine blaugrünen Kristalle von großer Reinheit sind bei Sammlern seltener facettierter Steine begehrt.",
            particularites = "Perfekte Spaltbarkeit in eine Richtung: gehört zu den heikelsten Edelsteinen beim Schleifen und Tragen.",
            inclusions = "Häufige Flüssigkeitseinschlüsse und feine innere Risse, im Einklang mit der vollkommenen Spaltbarkeit, die den Schliff heikel macht.",
            lithotherapie = "Euklas wird mit klarem Ausdruck und Gelassenheit assoziiert, eine Unterstützung für treffsichere Kommunikation."
        ),
        "topaze-bleue" to GemTranslation(
            nom = "Blauer Topas",
            descriptionCourte = "Das tiefe Blau, das durch Bestrahlung und Erhitzung eines farblosen Topas erzielt wird.",
            descriptionLongue = "Natürlicher blauer Topas ist äußerst selten; nahezu alle im Handel erhältlichen Steine („Sky“, „Swiss“, „London Blue“) stammen von farblosem Topas, der bestrahlt und anschließend erhitzt wird, um stabile und dauerhafte Blautöne zu entwickeln.",
            particularites = "Die Farbe wird nahezu systematisch durch Bestrahlung und anschließende Hitzebehandlung erzielt, stabil und dauerhaft.",
            inclusions = "Meist sehr rein (oft Ergebnis einer Bestrahlungsbehandlung); seltene Flüssigkeitseinschlüsse oder akzessorische Kristalle.",
            lithotherapie = "Blauer Topas soll eine ruhige Kommunikation fördern und dabei helfen, Gefühle gelassen auszudrücken."
        ),
        "tourmaline-bleue" to GemTranslation(
            nom = "Blauer Turmalin (Indigolith)",
            descriptionCourte = "Ein tiefes Blau, das sich vom kupferfarbenen Blaugrün der Paraíba-Tourmaline unterscheidet.",
            descriptionLongue = "Indigolith ist die blaue bis blaugrüne Varietät des Elbait-Turmalins, gefärbt durch Eisen, ohne das für die Paraíba-Tourmaline charakteristische Kupfer. Seine dunkleren, gedeckteren Farbtöne machen ihn zu einem eigenständigen Edelstein, der mitunter mit Aquamarin verwechselt wird.",
            particularites = "Unterscheidet sich von der Paraíba-Tourmaline durch das Fehlen von Kupfer und einen in der Regel dunkleren Ton.",
            inclusions = "Feine Trichite und charakteristische Hohlkanäle, je nach Lagerstätte mit gelegentlichen kristallinen Einschlüssen.",
            lithotherapie = "Der blaue Turmalin (Indigolith) wird mit Selbstausdruck und der Linderung kommunikationsbedingter Spannungen assoziiert."
        ),
        "zircon-bleu" to GemTranslation(
            nom = "Blauer Zirkon",
            descriptionCourte = "Der gefragteste Zirkon auf dem Markt, lebhaftes Blau durch Erhitzung erzielt.",
            descriptionLongue = "Blauer Zirkon, die meistgehandelte Farbe dieser Art, wird fast ausschließlich durch Hitzebehandlung von braunem kambodschanischem Zirkon gewonnen. Sein diamantartiger Glanz und seine starke Dispersion machen ihn zu einer geschätzten und erschwinglichen Alternative zum blauen Saphir.",
            particularites = "Nahezu systematische und stabile Hitzebehandlung; starke Dispersion, nahe an der des Diamanten.",
            inclusions = "Meist Ergebnis einer Wärmebehandlung; charakteristische Kantenverdopplung im Inneren und mitunter feine Spannungsrisse.",
            lithotherapie = "Blauer Zirkon soll geistige Ruhe und Klarheit bringen, eine Unterstützung für Phasen wichtiger Überlegungen."
        ),
        "hemimorphite" to GemTranslation(
            nom = "Hemimorphit",
            descriptionCourte = "Blaugrüne Kugelaggregate, die an Türkis oder Chrysokoll erinnern.",
            descriptionLongue = "Hemimorphit bildet traubenförmige, blaugrüne Aggregate, die häufig mit Türkis oder Chrysokoll verwechselt werden. Sein Name („Halbform“) stammt von seinen Kristallen, die an jedem Ende eine unterschiedliche Symmetrie aufweisen – eine kristallografische Besonderheit.",
            particularites = "Wird optisch häufig mit Chrysokoll oder Türkis verwechselt; die Bestimmung erfordert eine Härteprüfung.",
            inclusions = "Tritt meist als durchscheinende traubenförmige Aggregate auf; charakteristische faserige Struktur.",
            lithotherapie = "Hemimorphit wird mit authentischer Kommunikation und der Heilung emotionaler Verletzungen im Zusammenhang mit dem Selbstausdruck assoziiert."
        ),
        "shattuckite" to GemTranslation(
            nom = "Shattuckit",
            descriptionCourte = "Ein tiefes, seidiges Blau, ein seltener Verwandter des Chrysokolls.",
            descriptionLongue = "Shattuckit zeigt in faserigen Aggregaten ein intensives, seidiges Blau und tritt in den namibischen Kupferlagerstätten häufig zusammen mit Chrysokoll und Malachit auf. Er wird stets als Cabochon verarbeitet, um sein dezentes Schillern zur Geltung zu bringen.",
            particularites = "Zu weich für den Facettenschliff; wird stets als Cabochon geformt.",
            lithotherapie = "Shattuckit soll die Intuition stärken und eine bewusstere Kommunikation mit sich selbst erleichtern."
        ),
        "sapphirine" to GemTranslation(
            nom = "Saphirin",
            descriptionCourte = "Ein äußerst seltener blaugrauer Edelstein, ohne Verwandtschaft zum Korund.",
            descriptionLongue = "Trotz seines vielsagenden Namens ist der Saphirin nicht mit dem Korund verwandt: Er ist ein eigenständiges Silikat von blaugrauer bis violettlicher Farbe, das in metamorphen Gesteinen sehr hoher Temperatur entsteht, und zählt zu den seltensten facettierten Edelsteinen der Welt.",
            particularites = "Einer der seltensten geschliffenen Edelsteine der Welt: Es sind nur einige Dutzend facettierte Steine bekannt.",
            inclusions = "Eine sehr seltene Spezies; innere Einschlüsse wenig dokumentiert, da bekannte facettierte Steine sehr rar sind.",
            lithotherapie = "Als seltenes Mineral wird der Saphirin in der Lithotherapie mit tiefer Ruhe und emotionalem Schutz assoziiert."
        ),
        "dumortierite" to GemTranslation(
            nom = "Dumortierit",
            descriptionCourte = "Ein intensives Blauviolett in feinen Fasern, oft als Einschluss im Quarz.",
            descriptionLongue = "Dumortierit bildet faserige Aggregate von tiefem Blauviolett und tritt nur selten in Kristallen auf, die groß genug für einen eigenständigen Schliff sind – häufiger findet man ihn als dichte Einschlüsse, die einen massiven Quarz färben, der zu Cabochons oder Perlen verarbeitet wird.",
            particularites = "Häufiger anzutreffen als massiver, stark mit Dumortierit durchsetzter Quarz denn als reiner Kristall.",
            inclusions = "Tritt als dichte faserige Aggregate auf, oft eingeschlossen in Quarz (Dumortierit-Quarz), mit blauem Chatoyance-Effekt.",
            lithotherapie = "Dumortierit soll Geduld und geistige Disziplin fördern, eine Unterstützung bei anspruchsvollen Lernprozessen."
        ),
        "afghanite" to GemTranslation(
            nom = "Afghanit",
            descriptionCourte = "Ein erst kürzlich beschriebenes, lapisähnliches Blau aus denselben Lagerstätten wie Lapislazuli.",
            descriptionLongue = "Der 1968 wissenschaftlich beschriebene Afghanit findet sich in denselben Marmorlagerstätten wie der afghanische Lapislazuli und teilt mit ihm einen ähnlichen Blauton. Als facettierter Stein äußerst selten, bleibt er vor allem eine Sammlerkuriosität.",
            particularites = "Späte mineralogische Entdeckung (1968); facettierte Steine gehören zu den seltensten auf dem Markt.",
            inclusions = "Eine seltene, mit afghanischem Lapislazuli verbundene Spezies; kann feine Calcit- oder Pyriteinschlüsse aus dem Wirtsgestein enthalten.",
            lithotherapie = "Afghanit wird mit tiefer innerer Ruhe und einer Form sanften emotionalen Schutzes assoziiert."
        ),
        "saphir-bleu" to GemTranslation(
            nom = "Blauer Saphir",
            descriptionCourte = "Das Referenzblau der Haute Joaillerie.",
            descriptionLongue = "Der blaue Saphir verdankt seine Farbe Eisen und Titan. Das „samtige Blau“ der unbehandelten Steine aus Kaschmir bleibt für Kenner die absolute Referenz, gefolgt von Steinen aus Birma und Sri Lanka.",
            particularites = "Rutil-Einschlüsse in Form von „Seide“, die einen Asterismus (Sternsaphir) hervorrufen können.",
            inclusions = "Feine Rutilseide, von einem Spannungshof umgebene Zirkonkristalle, Glimmer- oder Feldspatkristalle sowie die für unbehandelte Steine charakteristische Farbzonierung in sechseckigen Bändern.",
            lithotherapie = "Als Stein der Weisheit seit der Antike soll der blaue Saphir geistige Klarheit, Loyalität und das Streben nach Wahrheit fördern."
        ),
        "saphir-auvergne" to GemTranslation(
            nom = "Auvergne-Saphir",
            descriptionCourte = "Ein französischer Korund mit tiefem blau-violettem Farbton, gewonnen aus dem vulkanischen Gestein der Auvergne.",
            descriptionLongue = "Auvergne-Saphire werden aus dem vulkanischen Gestein des Zentralmassivs gewonnen, insbesondere rund um Espaly-Saint-Marcel bei Le Puy-en-Velay, und sind eine französische Korundvarietät mit tiefem blau-violettem Farbton. Wie andere Saphire vulkanischen (basaltischen) Ursprungs zeichnen sie sich durch eine sehr intensive Farbe aus, sind jedoch meist klein und lassen sich nur selten zu mehr als einem Karat schleifen. Historisch im 19. Jahrhundert abgebaut, sind sie heute eine gefragte Kuriosität für Sammler und Liebhaber der französischen Gemmologie, weniger eine kommerzielle Quelle in größerem Umfang.",
            particularites = "Meist kleine Kristalle (nach dem Schliff selten über einem Karat), mit dem für Saphire basaltischen Ursprungs typischen, sehr intensiven blau-violetten Farbton.",
            inclusions = "Oft reich an für basaltische Saphire charakteristischen Einschlüssen: Plagioklas- und Pyroxenkristalle sowie ausgeprägte Farbzonierung, ein Kennzeichen seiner französischen vulkanischen Herkunft.",
            lithotherapie = "Wie andere Saphire wird auch der Auvergne-Saphir traditionell mit Weisheit und geistiger Klarheit assoziiert; sein französischer Ursprung macht ihn zu einem Stein, der besonders von Sammlern geschätzt wird, die dem nationalen mineralogischen Erbe verbunden sind."
        ),
        "aigue-marine" to GemTranslation(
            nom = "Aquamarin",
            descriptionCourte = "Kristallines „Meerwasser“.",
            descriptionLongue = "Sein Name, abgeleitet vom lateinischen „aqua marina“, weist auf seine hellblaue bis blaugrüne Farbe hin, die an Meerwasser erinnert. Der blaue Beryll zeichnet sich durch seine große Reinheit mit nur sehr wenigen mit bloßem Auge sichtbaren Einschlüssen aus.",
            particularites = "Wird häufig erhitzt, um den Grünanteil abzuschwächen und das Blau zu intensivieren.",
            inclusions = "Meist rein; Hohlkanäle parallel zur c-Achse, seltene Flüssigkeitseinschlüsse und akzessorische Kristalle.",
            lithotherapie = "Als Stein der Seefahrer wird Aquamarin traditionell mit Gelassenheit, Mut und ruhiger Kommunikation assoziiert, insbesondere auf Reisen."
        ),
        "tanzanite" to GemTranslation(
            nom = "Tansanit",
            descriptionCourte = "Nur eine einzige Quelle weltweit, am Fuße des Kilimandscharo.",
            descriptionLongue = "1967 entdeckt, kommt Tansanit ausschließlich im Gebiet von Merelani in Tansania vor. Sein starker Trichroismus lässt je nach Betrachtungswinkel Blau, Violett und Bordeaux erscheinen, bevor die standardmäßige Erhitzung den begehrten blauvioletten Farbton stabilisiert.",
            particularites = "Einzigartiges und zur Neige gehendes Vorkommen, gilt als Anlagestein.",
            inclusions = "Ausgeprägter trichroitischer Pleochroismus (Blau, Violett, Rotbraun); gelegentliche Flüssigkeitseinschlüsse und akzessorische Kristalle, nach dem Erhitzen meist nur wenige.",
            lithotherapie = "Tansanit soll die innere Transformation begleiten und ein ruhiges spirituelles Erwachen fördern."
        ),
        "lapis-lazuli" to GemTranslation(
            nom = "Lapislazuli",
            descriptionCourte = "Tiefes, goldgesprenkeltes Blau, seit der Antike verwendet.",
            descriptionLongue = "Lapislazuli ist ein Gestein, das hauptsächlich aus Lazurit besteht, verbunden mit Pyrit (goldene Einschlüsse) und Calcit (weiße Adern). Bereits im alten Ägypten verwendet und zum Pigment „Ultramarinblau“ vermahlen, ziert er seit Jahrtausenden Schmuck und Kunstobjekte.",
            particularites = "Gleichmäßig verteilte goldene Pyrit-Einschlüsse gelten als Qualitätsmerkmal.",
            lithotherapie = "Als Stein der Weisheit und Wahrheit seit dem alten Ägypten soll Lapislazuli das Selbstvertrauen und die Klarheit des Urteilsvermögens stärken."
        ),
        "turquoise" to GemTranslation(
            nom = "Türkis",
            descriptionCourte = "Emblematisches Blaugrün, geadert von Matrixgestein.",
            descriptionLongue = "Seit dem alten Ägypten verwendet und für zahlreiche indianische Kulturen heilig, verdankt der Türkis sein Blau dem Kupfer. Da er porös und weich ist, wird er häufig durch Harzimprägnierung stabilisiert, um der Beanspruchung in der Schmuckherstellung standzuhalten.",
            particularites = "Charakteristisches geädertes Matrixgestein; porös und empfindlich gegenüber Kosmetika und Chemikalien.",
            lithotherapie = "Als Schutzstein seit Jahrtausenden soll Türkis Gelassenheit, aufrichtige Kommunikation und Schutz auf Reisen fördern."
        ),
        "spinelle-bleu" to GemTranslation(
            nom = "Blauer Spinell",
            descriptionCourte = "Intensives Blau, mitunter durch Kobalt gefärbt.",
            descriptionLongue = "Der seltener als der rote Spinell vorkommende blaue Spinell verdankt seinen begehrtesten Farbton Kobaltspuren, die unter Glühlicht ein tiefes, samtiges Blau erzeugen.",
            particularites = "In der Regel unbehandelt, im Gegensatz zu vielen blauen Saphiren.",
            inclusions = "Akzessorische oktaedrische Kristalle und Wolken feiner Einschlüsse, vergleichbar mit anderen natürlich unbehandelten Spinellen.",
            lithotherapie = "Der blaue Spinell wird mit emotionaler Beruhigung und Neubeginn nach einer Phase der Anspannung assoziiert."
        ),
        "paraiba-tourmaline" to GemTranslation(
            nom = "Paraíba-Turmalin",
            descriptionCourte = "Elektrisches „Neon“-Blaugrün, einzigartig im Mineralreich.",
            descriptionLongue = "1989 im brasilianischen Bundesstaat Paraíba entdeckt, verdankt dieser Turmalin sein bis dahin unbekanntes, elektrisches Blaugrün Spuren von Kupfer und Mangan. Ähnliche Vorkommen wurden später in Mosambik und Nigeria gefunden. Er zählt zu den teuersten Farbedelsteinen der Welt.",
            particularites = "„Neon“-Farbe durch Kupfer, die bei keinem anderen Turmalin beobachtet wird.",
            inclusions = "Meist von großer Reinheit; feine Trichite und gelegentliche Hohlkanäle, wobei die hohe Reinheit zum Wert des Steins beiträgt.",
            lithotherapie = "Der Paraíba-Turmalin soll, im Einklang mit seiner strahlenden Farbe, tiefe Freude und erneuerte Vitalität anregen."
        ),
        "apatite-bleue" to GemTranslation(
            nom = "Neonblauer Apatit",
            descriptionCourte = "Elektrisches Türkisblau, dem breiten Publikum wenig bekannt.",
            descriptionLongue = "Der in den 1990er-Jahren auf Madagaskar entdeckte neonblaue Apatit zeigt einen sehr satten Türkiston, der dem der Paraíba-Tourmaline nahekommt, jedoch zu einem deutlich erschwinglicheren Preis. Seine relative Weichheit beschränkt seine Verwendung auf geschützten Schmuck.",
            particularites = "Mäßige Härte (5): eher für Ohrringe und Anhänger geeignet als für Ringe.",
            inclusions = "Häufige Flüssigkeitseinschlüsse und Wolken feiner Partikel; ein relativ zerbrechlicher Stein, der einen sorgfältigen Schliff erfordert.",
            lithotherapie = "Neonblauer Apatit wird mit Motivation und Klarheit persönlicher Ziele assoziiert, eine Unterstützung, um sich neu zu zentrieren."
        ),
        "cyanite" to GemTranslation(
            nom = "Kyanit (Disthen)",
            descriptionCourte = "Je nach Kristallachse unterschiedliche Härte.",
            descriptionLongue = "Kyanit (auch Disthen, griechisch „zweifache Widerstandsfähigkeit“) ist für seine Härteanisotropie bekannt: 4,5 entlang der Kristalllänge, 6,5 senkrecht dazu. Sein tiefes Blau erinnert mitunter an den Saphir, ist jedoch deutlich erschwinglicher.",
            particularites = "Anisotrope Härte macht den Schliff heikel; perfekte Spaltbarkeit in eine Richtung.",
            inclusions = "Vollkommene Spaltbarkeit in zwei Richtungen, die oft innere Risse verursacht; je nach Lagerstätte feine faserige Einschlüsse.",
            lithotherapie = "Kyanit (Disthen) soll die innere Ausrichtung fördern und eine fließende Kommunikation zwischen Herz und Verstand unterstützen."
        ),
        "benitoite" to GemTranslation(
            nom = "Benitoit",
            descriptionCourte = "Offizieller Stein Kaliforniens, bemerkenswerte Dispersion.",
            descriptionLongue = "1907 im San-Benito-County in Kalifornien entdeckt, fluoresziert Benitoit unter UV-Licht in leuchtendem Blau und weist eine höhere Dispersion auf als der Diamant. Die ursprüngliche Lagerstätte bleibt auch über ein Jahrhundert später nahezu die einzige Quelle für Edelsteinqualität weltweit.",
            particularites = "Leuchtend blaue Fluoreszenz unter UV-Licht; weltweit nahezu einzigartiges Vorkommen in Edelsteinqualität.",
            inclusions = "Extrem selten; kann feine Flüssigkeitseinschlüsse zeigen, wobei die meisten facettierten Steine sehr klein bleiben.",
            lithotherapie = "Als seltenes und kostbares Mineral wird Benitoit in der Lithotherapie mit spiritueller Erhebung und klarem Bewusstsein assoziiert."
        ),
        "jeremejevite" to GemTranslation(
            nom = "Jeremejewit",
            descriptionCourte = "Ein äußerst seltenes Aluminiumborat, hellblau bis farblos.",
            descriptionLongue = "1883 in Sibirien beschrieben und lange Zeit in Edelsteinqualität nicht auffindbar, wurde Jeremejewit erst in den 1970er-Jahren in Namibia in abbauwürdiger Menge wiederentdeckt. Sein klares, helles Blau und seine Seltenheit machen ihn zu einem bei Kennern begehrten Sammlerstein.",
            particularites = "Der Großteil der weltweiten Edelsteinproduktion stammt aus einem einzigen namibischen Massiv.",
            inclusions = "Eine sehr seltene Spezies; innere Einschlüsse wenig dokumentiert, da facettierbare Steine in Edelsteinqualität begrenzt sind (hauptsächlich Namibia).",
            lithotherapie = "Der äußerst seltene Jeremejewit wird mit geistiger Offenheit und der Verbindung zu einer höheren Form der Weisheit assoziiert."
        ),
        "violane" to GemTranslation(
            nom = "Violan",
            descriptionCourte = "Eine massive, kompakte Varietät des Diopsids, tiefes Blauviolett.",
            descriptionLongue = "Violan ist eine massive, kompakte Diopsid-Varietät von kräftigem Blauviolett, das dem mancher Azurite ähnelt, gefärbt durch Magnetit-Einschlüsse. Er wird stets als Cabochon oder poliertes Objekt verarbeitet.",
            particularites = "Typlokalität und historisches Vorkommen im italienischen Aostatal; stets als Cabochon geformt.",
            lithotherapie = "Violan, die violette Varietät des Diopsids, wird mit geistiger Beruhigung und Introspektion assoziiert, eine Unterstützung für die Meditation."
        ),
        "saphir-violet" to GemTranslation(
            nom = "Violetter Saphir",
            descriptionCourte = "Ein tiefes Violett an der Grenze zwischen blauem Saphir und Rubin.",
            descriptionLongue = "Der violette Saphir verdankt seinen Farbton einer Mischung aus Spuren von Eisen, Titan und Chrom und steht farblich an der Grenze zwischen blauem Saphir und Rubin. Manche Steine zeigen je nach Beleuchtung einen teilweisen Farbwechsel.",
            particularites = "Kann zwischen Tageslicht und Glühlicht einen leichten Farbwechsel zeigen.",
            inclusions = "Sektorale Farbzonierung, Rutilseide und kristalline Einschlüsse ähnlich anderen Korundvarietäten.",
            lithotherapie = "Violetter Saphir soll Spiritualität und Intuition fördern, eine Unterstützung in Phasen innerer Fragestellung."
        ),
        "purpurite" to GemTranslation(
            nom = "Purpurit",
            descriptionCourte = "Ein intensives, opakes Violettrot, ein seltener Schmuckstein aus Phosphat.",
            descriptionLongue = "Purpurit verdankt seinen Namen seiner kräftigen Purpurfarbe, die durch die Verwitterung von Mangan- und Eisenphosphaten entsteht. Opak und relativ weich, wird er für Schmuck und Kunstobjekte zu Cabochons geformt.",
            particularites = "Die Farbe kann an der Oberfläche bei längerer Lichteinwirkung verblassen; zu schützen.",
            lithotherapie = "Purpurit wird mit persönlicher Transformation und innerer Stärke in Zeiten des Wandels assoziiert."
        ),
        "hackmanite" to GemTranslation(
            nom = "Hackmanit",
            descriptionCourte = "Ein Chamäleonstein, der unter UV-Licht rosa wird und im Tageslicht wieder verblasst.",
            descriptionLongue = "Hackmanit ist eine tenebreszente Sodalith-Varietät: Unter UV-Bestrahlung entwickelt er einen rosa-violetten Farbton, der bei Tageslicht anschließend allmählich wieder verblasst – ein faszinierendes und unter Edelsteinen einzigartiges reversibles Phänomen.",
            particularites = "Reversibles Tenebreszenz-Phänomen: Die Farbe variiert je nach kürzlicher UV- oder Lichteinwirkung.",
            inclusions = "Zeichnet sich durch Tenebreszenz (reversibler Farbwechsel im Licht) aus; kristalline Einschlüsse je nach afghanischer oder grönländischer Lagerstätte unterschiedlich.",
            lithotherapie = "Hackmanit soll die Intuition anregen und eine Form energetischen Schutzes bieten, insbesondere während der Meditation."
        ),
        "lepidolite" to GemTranslation(
            nom = "Lepidolith",
            descriptionCourte = "Der lilafarbene Lithiumglimmer, oft vergesellschaftet mit rosa Turmalin.",
            descriptionLongue = "Lepidolith ist ein lithiumreicher Glimmer von charakteristisch lila bis mauvefarbener Tönung, der häufig in Pegmatiten zusammen mit rosa Turmalin und Kunzit vorkommt, mit denen er dieselbe Lithiumchemie teilt.",
            particularites = "Zu weich und schiefrig für facettierten Schmuck; wird als Cabochon, Perlen und dekorative Objekte verarbeitet.",
            lithotherapie = "Reich an natürlichem Lithium, wird Lepidolith traditionell nachgesagt, Stress und Angst zu lindern und einen ruhigen Schlaf zu fördern."
        ),
        "stichtite" to GemTranslation(
            nom = "Stichtit",
            descriptionCourte = "Ein violett-rosafarbener Lilaton, oft durchzogen von grünem Serpentin (Atlantasit).",
            descriptionLongue = "Stichtit bildet violett-rosafarbene Massen, die häufig mit grünem Serpentin verwachsen sind und den „Atlantasit\" bilden, eine bei Cabochons und Ziergegenständen sehr gefragte Kombination.",
            particularites = "Extrem weich: nur für Cabochons und dekorative Objekte geeignet, die wenig Stößen ausgesetzt sind.",
            inclusions = "Tritt meist als durchscheinende faserige Aggregate auf, oft verbunden mit Serpentin.",
            lithotherapie = "Stichtit wird mit Selbstmitgefühl und Mitgefühl gegenüber anderen in Verbindung gebracht und soll Vergebung und emotionale Beruhigung fördern."
        ),
        "amethyste" to GemTranslation(
            nom = "Amethyst",
            descriptionCourte = "Der Stein der Mäßigung.",
            descriptionLongue = "Amethyst verdankt seine violette Farbe Spuren von Eisen in Verbindung mit natürlicher Bestrahlung. Obwohl reichlich vorhanden und erschwinglich, wurde er jahrhundertelang von Adel und Klerus getragen, als Symbol für Nüchternheit und Spiritualität.",
            particularites = "Kann bei längerer Sonnenlichteinwirkung ausbleichen.",
            inclusions = "Chevronförmige Farbzonierung (Brasilianer Zwillingsgesetz), Schleier feiner Flüssigkeitseinschlüsse, mitunter Wachstumsphantomkristalle.",
            lithotherapie = "Amethyst zählt in der Lithotherapie zu den bekanntesten Steinen zur Linderung von Stress, zur Förderung eines ruhigen Schlafs sowie zur Unterstützung von Meditation und Spiritualität."
        ),
        "spinelle-violet" to GemTranslation(
            nom = "Violetter Spinell",
            descriptionCourte = "Härte und Glanz für eine dauerhafte Alternative.",
            descriptionLongue = "Violetter Spinell verbindet eine gute Härte mit dem Fehlen von Spaltbarkeit, was ihn zu einer sehr widerstandsfähigen Alternative zu Amethyst oder violettem Saphir macht, mit einem besonders lebendigen Glasglanz.",
            particularites = "In der Regel unbehandelt.",
            inclusions = "Kleine oktaedrische Kristalle und für die Spezies typische feine wolkige Einschlüsse, von Natur aus unbehandelt.",
            lithotherapie = "Violetter Spinell wird mit spirituellem Neubeginn und innerer Gelassenheit in Verbindung gebracht."
        ),
        "iolite" to GemTranslation(
            nom = "Iolith",
            descriptionCourte = "Der „Wikinger-Saphir\".",
            descriptionLongue = "Iolith verdankt seinen Namen dem griechischen „ios\" (violett). Sein spektakulärer Pleochroismus lässt seine Farbe je nach Betrachtungswinkel von Blauviolett zu einem fast farblosen Blassgelb wechseln – eine Eigenschaft, die Wikingerseefahrer angeblich zur Orientierung nutzten.",
            particularites = "Sehr ausgeprägter trichroitischer Pleochroismus, entscheidend für die Ausrichtung beim Schleifen.",
            inclusions = "Hämatit-Einschlüsse als feine orientierte Plättchen, verantwortlich für einen in manchen Lagerstätten „bloodshot iolite\" genannten Chatoyance-Effekt.",
            lithotherapie = "Von Wikingerseefahrern zur Orientierung genutzt, soll Iolith Intuition und visionäre Klarheit bei Lebensentscheidungen stärken."
        ),
        "grenat-rhodolite-violet" to GemTranslation(
            nom = "Violetter Rhodolith-Granat",
            descriptionCourte = "Purpurfarbener Ton, der sich je nach Beleuchtung verändert.",
            descriptionLongue = "Manche Rhodolithe zeigen unter natürlichem Licht eine besonders ausgeprägte purpurviolette Dominanz und bieten damit eine kostengünstige Alternative zu selteneren violetten Steinen.",
            particularites = "Stabile Farbe, niemals behandelt.",
            inclusions = "Gelegentliche akzessorische Kristalle und feine innere Fibrillen, vergleichbar mit klassischem Rhodolith.",
            lithotherapie = "Diese violette Rhodolith-Varietät wird mit dem Gleichgewicht zwischen Leidenschaft und emotionaler Gelassenheit in Verbindung gebracht."
        ),
        "sugilite" to GemTranslation(
            nom = "Sugilith",
            descriptionCourte = "Intensives Violett, in den 1970er-Jahren populär geworden.",
            descriptionLongue = "1944 erstmals in Japan beschrieben und später durch die in den 1970er-Jahren entdeckten südafrikanischen Vorkommen populär geworden, zeigt Sugilith ein tiefes, opak bis durchscheinendes Violett bis Purpur und wird als Cabochon geschliffen.",
            particularites = "Wird stets als Cabochon geschliffen; das wichtigste südafrikanische Vorkommen ist heute erschöpft.",
            lithotherapie = "Sugilith soll spirituellen Schutz bieten und Trost in Zeiten der Trauer oder großer emotionaler Erschöpfung spenden."
        ),
        "charoite" to GemTranslation(
            nom = "Charoit",
            descriptionCourte = "Ein einziges Vorkommen in Sibirien.",
            descriptionLongue = "Erst 1978 beschrieben, ist Charoit nur von einem einzigen Vorkommen am Ufer des Flusses Tschara in Sibirien bekannt. Sein wirbelndes violett-weißes Muster, das durch die Verflechtung kristalliner Fasern entsteht, macht ihn zu einem sofort erkennbaren Schmuckstein.",
            particularites = "Weltweit einziges Vorkommen; charakteristisches wirbelndes Muster, stets als Cabochon geschliffen.",
            inclusions = "Dichte charakteristische faserig-radialstrahlige Struktur, durchzogen von schwarzen Manganadern (Ägirin) und mitunter weißem Calcit.",
            lithotherapie = "Charoit wird mit tiefgreifender innerer Transformation und dem Mut, sich Veränderungen zu stellen, in Verbindung gebracht."
        ),
        "taaffeite" to GemTranslation(
            nom = "Taaffeit",
            descriptionCourte = "Das erste Mineral, das in einem bereits geschliffenen Stein entdeckt wurde.",
            descriptionLongue = "1945 vom Gemmologen Richard Taaffe in einem bereits facettierten und fälschlicherweise als Spinell eingestuften Stein identifiziert, zählt Taaffeit weiterhin zu den seltensten Edelsteinen der Welt, in zarten Malven- bis Lilatönen.",
            particularites = "Lange mit Spinell verwechselt; unterscheidet sich durch eine Doppelbrechung, die Spinell nicht besitzt.",
            inclusions = "Eine extrem seltene Spezies, lange mit Spinell verwechselt; innere Einschlüsse wenig dokumentiert.",
            lithotherapie = "Als äußerst seltenes Mineral wird Taaffeit in der Lithotherapie mit Bewusstseinserweiterung und der Einzigartigkeit des persönlichen Weges assoziiert."
        ),
        "axinite" to GemTranslation(
            nom = "Axinit",
            descriptionCourte = "Beilklingenförmige Kristalle, starker Pleochroismus.",
            descriptionLongue = "Sein Name stammt vom griechischen „axine\" (Beil) und bezieht sich auf die scharfe, flache Form seiner Kristalle. Axinit zeigt je nach Betrachtungswinkel einen ausgeprägten Pleochroismus von Braunviolett bis Gelbgrün und wird von Sammlern seltener Steine geschätzt.",
            particularites = "Ausgeprägter trichroitischer Pleochroismus; Kristalle historisch erstmals in Frankreich (Dauphiné) beschrieben.",
            inclusions = "Je nach Lagerstätte feine Flüssigkeitseinschlüsse und akzessorische Kristalle; ein stark pleochroitischer Stein, der präzise geschliffen wird, um seine Farbe zu offenbaren.",
            lithotherapie = "Axinit soll Erdung und Konzentration fördern und Halt geben, um in unruhigen Zeiten zentriert zu bleiben."
        ),
        "cobaltocalcite" to GemTranslation(
            nom = "Kobaltocalcit",
            descriptionCourte = "Ein leuchtendes Bonbonrosa, eine durch Kobalt gefärbte Calcit-Varietät.",
            descriptionLongue = "Kobaltocalcit (kobalthaltiger Calcit) zeigt ein elektrisierendes leuchtendes Rosa, das auf Kobaltspuren zurückgeht, und bildet traubige Krusten, die bei Sammlern sehr begehrt sind. Seine extreme Weichheit schließt jede gängige Schmucknutzung aus.",
            particularites = "Extrem weich und wie jeder Calcit empfindlich gegenüber Säuren; ausschließlich Sammlerstein.",
            lithotherapie = "Kobaltocalcit wird mit Selbstliebe und Zärtlichkeit in Verbindung gebracht, ein sanfter emotionaler Halt in sensiblen Zeiten."
        ),
        "thulite" to GemTranslation(
            nom = "Thulit",
            descriptionCourte = "Die rosafarbene Varietät des Zoisits, verwandt mit dem blauen Tansanit.",
            descriptionLongue = "Thulit ist die rosa bis rotrosa Varietät des Zoisits, gefärbt durch Mangan – dasselbe Mineral wie Tansanit, jedoch ohne die Erhitzung, die dessen Blauviolett hervorbringt. In Norwegen entdeckt, verdankt er dort seinen Namen (Thule).",
            particularites = "Fast immer opak und als Cabochon verarbeitet; transparente facettierte Steine sind selten.",
            lithotherapie = "Thulit soll Freude und emotionale Vitalität neu entfachen und dabei helfen, wieder Zugang zu positiven Gefühlen zu finden."
        ),
        "rhodonite" to GemTranslation(
            nom = "Rhodonit",
            descriptionCourte = "Ein tiefes Rosa, durchzogen von schwarzen Manganadern.",
            descriptionLongue = "Rhodonit zeigt ein kräftiges Rosa bis Rotrosa, durchzogen von schwarzen Adern aus Manganoxiden, die ihm ein charakteristisches marmoriertes Erscheinungsbild verleihen. Als Nationalstein Russlands schmückte er historisch die kaiserlichen Paläste.",
            particularites = "Nationalstein Russlands; die schwarzen Manganadern bilden ein charakteristisches Erkennungsmerkmal.",
            lithotherapie = "Rhodonit wird traditionell mit Vergebung und der Heilung emotionaler Wunden in Verbindung gebracht, insbesondere nach einer Trennung."
        ),
        "topaze-rose" to GemTranslation(
            nom = "Rosa Topas",
            descriptionCourte = "Das seltenste natürliche Rosa des Topas, historisch aus Pakistan gefördert.",
            descriptionLongue = "Natürlicher, unbehandelter rosa Topas ist deutlich seltener als blauer oder farbloser Topas. Das historische Vorkommen von Katlang in Pakistan lieferte einige der schönsten Steine in einem zarten Pfirsichrosa.",
            particularites = "Natürliches, unbehandeltes Rosa ist selten; zu unterscheiden vom rosa Topas, der durch Hitzebehandlung brauner Steine entsteht.",
            inclusions = "Gelegentliche Flüssigkeitseinschlüsse und feine innere Risse; meist gute Reinheit.",
            lithotherapie = "Rosa Topas soll Sanftmut in Beziehungen fördern und das Herz für aufrichtige Liebe öffnen."
        ),
        "quartz-rose" to GemTranslation(
            nom = "Rosenquarz",
            descriptionCourte = "Der pastellfarbene rosa Quarz, in allen Traditionen der Stein der Liebe.",
            descriptionLongue = "Rosenquarz, gefärbt durch Spuren von Titan, Mangan oder mikroskopisch kleine faserige Dumortierit-Einschlüsse, wird in den meisten Kulturen mit Liebe und Sanftheit assoziiert. Transparente, facettierbare Kristalle sind selten; das durchscheinende Massenmaterial ist die häufigste Form.",
            particularites = "Manche Steine zeigen einen sechsstrahligen Asterismus (Sternrosenquarz), der als Cabochon geschliffen wird.",
            inclusions = "Oft leicht getrübt durch feine faserige Dumortierit-Einschlüsse; kann als Cabochon einen Sterneffekt zeigen.",
            lithotherapie = "Als Stein der bedingungslosen Liebe schlechthin soll Rosenquarz Herzschmerz lindern und Zärtlichkeit gegenüber sich selbst und anderen fördern."
        ),
        "phosphosiderite" to GemTranslation(
            nom = "Phosphosiderit",
            descriptionCourte = "Ein sanftes Rosaviolett in nierenförmigen Krusten, verwandt mit Variscit.",
            descriptionLongue = "Phosphosiderit bildet nierenförmige Krusten in Rosalila bis Violett, chemisch nahe verwandt mit dem grünen Variscit, jedoch durch Eisen gefärbt. Wird stets als Cabochon verarbeitet, um seinen seidigen Schimmer zur Geltung zu bringen.",
            particularites = "Härte ähnlich der von Variscit; stets als Cabochon verarbeitet.",
            inclusions = "Dichte faserig-radialstrahlige Struktur mit seidigem Glanz, wegen ihrer begrenzten Durchscheinung selten facettiert.",
            lithotherapie = "Phosphosiderit wird mit Loslassen und innerer Sanftheit in Verbindung gebracht, eine Unterstützung während der Meditation."
        ),
        "morganite" to GemTranslation(
            nom = "Morganit",
            descriptionCourte = "Zartes Rosa bis Pfirsich, 1911 benannt.",
            descriptionLongue = "Vom Gemmologen George Kunz zu Ehren des Finanziers und Sammlers J.P. Morgan benannt, zeigt Morganit einen zarten, durch Mangan hervorgerufenen Ton von Rosa bis Pfirsich. Sehr rein, wird er oft zu großen, eindrucksvollen Steinen geschliffen.",
            particularites = "Wird häufig erhitzt, um einen orangefarbenen Anteil zu mildern und ein reines Rosa hervorzubringen.",
            inclusions = "Wachstumskanäle parallel zur c-Achse und gelegentliche Flüssigkeitseinschlüsse; meist sehr rein.",
            lithotherapie = "Morganit soll das Herz für Mitgefühl und Selbstliebe öffnen und emotionale Ängste lindern."
        ),
        "kunzite" to GemTranslation(
            nom = "Kunzit",
            descriptionCourte = "Ausgeprägter Pleochroismus, ein empfindlicher Stein.",
            descriptionLongue = "1902 entdeckt und nach dem Gemmologen George Frederick Kunz benannt, zeigt Kunzit ein verführerisches Rosalila. Er ist jedoch empfindlich gegenüber längerer Lichteinwirkung und Temperaturschocks und sollte nur gelegentlich getragen werden.",
            particularites = "Deutliche Spaltbarkeit in zwei Richtungen; vor längerer direkter Lichteinwirkung zu schützen.",
            inclusions = "Feine Flüssigkeitseinschlüsse und vollkommene Spaltbarkeit in zwei Richtungen, die den Schliff heikel machen; ein stoßempfindlicher Stein.",
            lithotherapie = "Kunzit wird mit bedingungsloser Liebe und tiefer emotionaler Beruhigung in Verbindung gebracht, eine Unterstützung beim Loslassen angestauter Spannungen."
        ),
        "saphir-rose" to GemTranslation(
            nom = "Rosa Saphir",
            descriptionCourte = "An der Grenze zwischen Rubin und Saphir.",
            descriptionLongue = "Wie der Rubin durch Chrom gefärbt, jedoch in geringerer Konzentration, liegt der rosa Saphir an der konventionellen Grenze zum Rubin: Ab einer bestimmten Sättigung wird der Stein als Rubin eingestuft.",
            particularites = "Die Grenze zwischen Rubin und rosa Saphir bleibt unter gemmologischen Labors umstritten.",
            inclusions = "Feine Rutilseide, Zirkonkristalle mit Spannungshof und bandförmige Farbzonierung, vergleichbar mit dem Rubin, dessen Spezies er teilt.",
            lithotherapie = "Rosa Saphir soll aufrichtige Liebe und Harmonie in emotionalen Beziehungen fördern."
        ),
        "tourmaline-rose" to GemTranslation(
            nom = "Rosa Turmalin",
            descriptionCourte = "Mangan für einen zarten Farbton.",
            descriptionLongue = "Weniger gesättigt als Rubellit, zeigt rosa Turmalin sanfte Töne von Blassrosa bis Bonbonrosa, oft in Verbindung mit den für die Gruppe charakteristischen zwei- oder dreifarbigen Kristallen.",
            particularites = "Kristalle sind oft zoniert, Ursprung der zweifarbigen Turmaline.",
            inclusions = "Für die Spezies typische Wattefaden-Trichite und Hohlkanäle, mitunter mit kristallinen Glimmereinschlüssen.",
            lithotherapie = "Rosa Turmalin wird mit Zärtlichkeit und der Heilung emotionaler Wunden im Zusammenhang mit Liebe und Bindung in Verbindung gebracht."
        ),
        "rhodochrosite" to GemTranslation(
            nom = "Rhodochrosit",
            descriptionCourte = "Konzentrische rosa und weiße Bänder.",
            descriptionLongue = "Erkennbar an seinen konzentrischen rosa-weißen Mustern, die an Baumringe erinnern, ist Rhodochrosit ein geschätzter Zier- und Sammlerstein, jedoch zu empfindlich für den täglichen Ringgebrauch.",
            particularites = "Sehr empfindlich und säureempfindlich; nur für Sammlerstücke oder geschützte Anhänger geeignet.",
            lithotherapie = "Rhodochrosit soll Selbstliebe und die Heilung des inneren Kindes fördern, eine Unterstützung bei tiefer emotionaler Arbeit."
        ),
        "saphir-blanc" to GemTranslation(
            nom = "Weißer Saphir",
            descriptionCourte = "Der Korund ohne färbende Spurenelemente, eine dezente Alternative zum Diamanten.",
            descriptionLongue = "Frei von den metallischen Spuren, die Rubin oder blauen Saphir färben, bietet der weiße Saphir (oder „Leukosaphir\") einen dem Diamanten nahen Glanz zu einem deutlich niedrigeren Preis und wurde lange als Ersatzstein in Uhrmacherei und Schmuck verwendet.",
            particularites = "Geringere Dispersion als Diamant, aber nahezu gleiche Härte; hervorragende Alltagsbeständigkeit.",
            inclusions = "Meist mit bloßem Auge sehr rein; kann leichte Wachstumszonierung und seltene akzessorische Mineralkristalle zeigen.",
            lithotherapie = "Weißer Saphir soll geistige Klarheit und Reinheit der Absicht bei wichtigen Entscheidungen fördern."
        ),
        "topaze-blanche" to GemTranslation(
            nom = "Weißer Topas",
            descriptionCourte = "Der Topas in seiner reinsten und häufigsten Form, farblos und klar.",
            descriptionLongue = "Farbloser Topas ist tatsächlich die in der Natur am weitesten verbreitete Farbe dieser Art – die im Handel erhältlichen blauen Topase stammen fast immer durch Behandlung aus ihm. Klar und brillant, dient er auch als preisgünstiger Ersatzstein für Diamanten.",
            particularites = "Wichtigstes Ausgangsmaterial für die Herstellung von durch Bestrahlung behandeltem blauem Topas.",
            inclusions = "In der Regel ein sehr reiner Stein; wenige mit bloßem Auge sichtbare Einschlüsse.",
            lithotherapie = "Weißer Topas wird mit geistiger Klarheit und dem Streben nach Wahrheit bei Lebensentscheidungen in Verbindung gebracht."
        ),
        "hambergite" to GemTranslation(
            nom = "Hambergit",
            descriptionCourte = "Ein farbloser Edelstein von extremer Seltenheit, ebenso zerbrechlich wie brillant.",
            descriptionLongue = "Hambergit ist ein farbloser bis kaum getönter, seltener und brillanter Edelstein, jedoch von extremer Zerbrechlichkeit aufgrund einer vollkommenen Spaltbarkeit, die ihn zu einer gefürchteten Herausforderung für Lapidare macht – einer der am seltensten auf dem Markt anzutreffenden Steine.",
            particularites = "Vollkommene Spaltbarkeit macht Schliff und Tragen als Schmuckstück besonders riskant; Sammlerstein.",
            inclusions = "Eine seltene Spezies mit vollkommener Spaltbarkeit; innere Einschlüsse wenig dokumentiert, da Steine in Edelsteinqualität selten bleiben.",
            lithotherapie = "Hambergit, ein seltenes Mineral, wird in der Lithotherapie mit geistiger Klarheit und Konzentration in Verbindung gebracht."
        ),
        "petalite" to GemTranslation(
            nom = "Petalith",
            descriptionCourte = "Ein selten facettiertes Lithiumerz, dezent und klar.",
            descriptionLongue = "Petalith, eine bedeutende Quelle für industrielles Lithium, bringt gelegentlich farblose bis leicht getönte Edelsteinkristalle hervor, die eher für Sammler als für den breiten Schmuckmarkt geschliffen werden.",
            particularites = "Wird vor allem als Lithiumerz abgebaut; facettierbare Edelsteinqualitäten sind eine Randerscheinung.",
            inclusions = "Meist sehr rein; kann feine Flüssigkeitseinschlüsse und eine vollkommene Spaltbarkeit zeigen, die den Schliff heikel macht.",
            lithotherapie = "Petalith soll eine tiefe Gelassenheit fördern und wird besonders geschätzt, um die Meditation zu begleiten."
        ),
        "phenakite" to GemTranslation(
            nom = "Phenakit",
            descriptionCourte = "Ein farbloser Edelstein, so klar, dass er lange mit Quarz oder Diamant verwechselt wurde.",
            descriptionLongue = "Der Name des Phenakits (aus dem Griechischen für „Betrüger\") rührt von seiner täuschenden Ähnlichkeit mit Quarz oder sogar rohem Diamant her. Selten und mit schönem Glanz facettiert, wird er vor allem von versierten Sammlern geschätzt.",
            particularites = "Sein griechischer Name bedeutet „Betrüger\" und bezieht sich auf die historische Verwechslung mit Quarz.",
            inclusions = "Oft von großer Reinheit; je nach Lagerstätte seltene Flüssigkeitseinschlüsse oder akzessorische Kristalle.",
            lithotherapie = "Phenakit wird mit Bewusstseinserweiterung und großer spiritueller Klarheit assoziiert und fortgeschrittenen meditativen Praktiken vorbehalten."
        ),
        "bytownite" to GemTranslation(
            nom = "Bytownit",
            descriptionCourte = "Ein selten facettierbarer Feldspat, das kalziumreiche Ende der Plagioklasreihe.",
            descriptionLongue = "Bytownit, reich an Kalzium innerhalb der Plagioklasreihe (zwischen Labradorit und Anorthit), bildet ausnahmsweise klare Kristalle, die rein genug sind, um facettiert zu werden, hauptsächlich im Kongo und in Indien.",
            particularites = "Kalziumreiches Glied der Plagioklasreihe, zwischen Labradorit und reinem Anorthit.",
            inclusions = "Kann feine Entmischungslamellen und Kupfereinschlüsse zeigen, die bei Steinen nahe dem Labradorit für einen Chatoyance-Effekt sorgen.",
            lithotherapie = "Bytownit soll eine lichtvolle Erdung bieten, zwischen sanftem Schutz und geistiger Klarheit."
        ),
        "hyalite" to GemTranslation(
            nom = "Hyalith",
            descriptionCourte = "Ein farbloser, transparenter Opal, der unter UV-Licht grün fluoresziert.",
            descriptionLongue = "Hyalith ist ein nicht edler Opal, farblos und in dünnen Lagen völlig transparent, bekannt für seine leuchtend grüne Fluoreszenz unter ultraviolettem Licht, die auf Uranspuren zurückgeht – ein bei Liebhabern fluoreszierender Mineralien beliebtes Schauspiel.",
            particularites = "Leuchtend grüne Fluoreszenz unter UV-Licht durch Uranspuren, ohne das Opaleszieren des Edelopals.",
            inclusions = "Eine meist farblose und sehr reine Opalvarietät, die aufgrund von Uranspuren unter UV-Licht mitunter fluoresziert.",
            lithotherapie = "Diese farblose Opalvarietät wird mit Reinheit und geistiger Leichtigkeit in Verbindung gebracht."
        ),
        "anhydrite" to GemTranslation(
            nom = "Anhydrit",
            descriptionCourte = "Das wasserfreie Kalziumsulfat, trockener Vetter des Gipses, selten geschliffen.",
            descriptionLongue = "Anhydrit, chemisch nahe verwandt mit Gips, jedoch ohne Kristallwasser, kommt in farblosen bis blassblauen oder violetten Tönen vor. Seine Weichheit und Spaltbarkeit beschränken ihn auf eine vertrauliche Sammlernutzung.",
            particularites = "Wandelt sich bei anhaltendem Wasserkontakt langsam in Gips um, ein natürliches Phänomen mineralischer Umwandlung.",
            inclusions = "Kristalle oft in Spaltblättchen aufgeteilt, mit feinen Flüssigkeitseinschlüssen; wegen ihrer Zerbrechlichkeit selten facettiert.",
            lithotherapie = "Anhydrit soll Struktur und Klarheit in der Organisation der eigenen Gedanken und des Alltags bringen."
        ),
        "baryte" to GemTranslation(
            nom = "Baryt",
            descriptionCourte = "Ein dichtes, weiches Mineral, selten facettiert, aber in Kristallen spektakulär.",
            descriptionLongue = "Baryt (Bariumsulfat) verdankt seinen Namen seiner für ein nichtmetallisches Mineral bemerkenswerten Dichte. Seine tafeligen, oft farblosen bis honiggelben Kristalle werden trotz ihrer großen Zerbrechlichkeit gelegentlich für Sammler facettiert.",
            particularites = "Außergewöhnlich hohe Dichte für ein nichtmetallisches Mineral, dient als Erkennungsmerkmal.",
            inclusions = "Tafelige Kristalle, die je nach Lagerstätte oft feine gefärbte Partikel einschließen; wegen ihrer Zerbrechlichkeit selten facettiert.",
            lithotherapie = "Baryt wird mit Erdung und emotionaler Stabilität in Verbindung gebracht, eine Unterstützung in Zeiten des Wandels."
        ),
        "aragonite" to GemTranslation(
            nom = "Aragonit",
            descriptionCourte = "Das Polymorph des Kalksteins, das auch Perlen und Korallen bildet.",
            descriptionLongue = "Aragonit ist das orthorhombische Polymorph des Kalziumkarbonats – dieselbe Substanz, aus der Perlen, Muschelschalen und Korallen bestehen. Seine terrestrischen Kristalle, meist farblos bis blassgelb, werden vor allem im Rohzustand gesammelt.",
            particularites = "Langfristig instabil: wandelt sich allmählich in Calcit um, sein stabileres Polymorph.",
            inclusions = "Struktur oft zu charakteristischen Pseudohexagonen verzwillingt, mit feinen Flüssigkeitseinschlüssen.",
            lithotherapie = "Aragonit soll Erdung und Geduld fördern und dabei helfen, den natürlichen Lauf der Dinge zu akzeptieren."
        ),
        "calcite" to GemTranslation(
            nom = "Calcit",
            descriptionCourte = "Das häufigste Mineral der Erdkruste, gelegentlich facettiert.",
            descriptionLongue = "Calcit ist eines der am weitesten verbreiteten Minerale der Welt und tritt in einer außergewöhnlichen Vielfalt von Kristallformen auf. Zu weich für den täglichen Gebrauch, wird er dennoch von Sammlern wegen seiner spektakulären Doppelbrechung (Bildverdopplung durch den Stein hindurch) facettiert.",
            particularites = "Extreme Doppelbrechung: Ein durch einen klaren Calcitkristall betrachtetes Objekt erscheint verdoppelt.",
            inclusions = "Starke Doppelbrechung, die zu einer mit bloßem Auge sichtbaren deutlichen Kantenverdopplung im Inneren führt; vollkommene Spaltbarkeit in drei Richtungen.",
            lithotherapie = "Calcit wird traditionell zur Reinigung der umgebenden Energien und zur Förderung geistiger Klarheit verwendet."
        ),
        "cerusite" to GemTranslation(
            nom = "Cerussit",
            descriptionCourte = "Ein Bleierz mit spektakulärer Dispersion, selten als facettierter Stein.",
            descriptionLongue = "Cerussit, ein Bleierz, besitzt eine höhere optische Dispersion als der Diamant und erzeugt facettiert bemerkenswerte Feuerblitze. Seine sehr hohe Dichte und große Zerbrechlichkeit machen ihn ausschließlich zu einem Sammleredelstein.",
            particularites = "Höhere optische Dispersion als Diamant; sehr hohe, für Blei charakteristische Dichte.",
            inclusions = "Starker diamantartiger Glanz und hohe Dispersion; häufige sechsstrahlige Sternzwillinge, ein heikel zu schleifender Stein.",
            lithotherapie = "Cerussit wird mit Erdung und einer sanften inneren Transformation in Verbindung gebracht."
        ),
        "montebrasite" to GemTranslation(
            nom = "Montebrasit",
            descriptionCourte = "Ein dezenter Lithium-Edelstein, verwandt mit Amblygonit.",
            descriptionLongue = "Montebrasit, ein naher Verwandter des Amblygonits, von dem er sich nur durch seinen Hydroxylgehalt unterscheidet, liefert farblose bis blassgelbe Steine, die vor allem für Liebhaber lithiumhaltiger Raritäten geschliffen werden.",
            particularites = "Typlokalität und namensgebendes Vorkommen im Département Creuse in Frankreich, im 19. Jahrhundert entdeckt.",
            inclusions = "Gelegentliche Flüssigkeitseinschlüsse, nahe verwandt mit Amblygonit, dessen hydroxylreiche Varietät sie darstellt.",
            lithotherapie = "Montebrasit soll geistige Klarheit und Urteilsvermögen bei wichtigen Entscheidungen fördern."
        ),
        "diamant" to GemTranslation(
            nom = "Diamant",
            descriptionCourte = "Der härteste bekannte Edelstein.",
            descriptionLongue = "Unter sehr hohem Druck und hoher Temperatur im Erdmantel entstanden, besteht der Diamant aus kristallisiertem reinem Kohlenstoff. Seine maximale Härte, seine starke Dispersion (das „Feuer\") und sein diamantartiger Glanz machen ihn zum Referenzstein der Haute Joaillerie, bewertet nach den „4C\": Carat, Color, Clarity und Cut.",
            particularites = "Einziger Edelstein mit der Härte 10; für bedeutende Steine ist eine Zertifizierung (GIA, HRD...) unerlässlich.",
            inclusions = "Kristalle von Tiefenmineralien (Granat, Olivin), Wolken feiner Partikel, Federn (Risse), schwarze Kohlenstoffpunkte und Wachstumslinien; Einschlüsse bestimmen die Reinheit nach der GIA-Skala.",
            lithotherapie = "Seit jeher Symbol für Kraft und Reinheit, soll der Diamant die umgebenden Energien verstärken sowie Klarheit der Absicht und Selbstvertrauen stärken."
        ),
        "zircon-blanc" to GemTranslation(
            nom = "Weißer Zirkon",
            descriptionCourte = "Starke Dispersion, lange als Diamantersatz verwendet.",
            descriptionLongue = "Nicht zu verwechseln mit Zirkonia (einem synthetischen Material), ist Zirkon ein natürlicher Edelstein, dessen starke Lichtdispersion mit der des Diamanten konkurriert, was ihn historisch zu einem beliebten Ersatzstein gemacht hat.",
            particularites = "Wird häufig erhitzt, um aus braunem Zirkon Farblosigkeit zu erzielen; Facettenkanten erscheinen manchmal verdoppelt.",
            inclusions = "Starke Doppelbrechung, die zu einer sichtbaren Verdopplung der hinteren Facettenkanten führt; nach dem Erhitzen meist reiner Stein.",
            lithotherapie = "Weißer Zirkon wird mit geistiger Klarheit und Reinheit der Absicht in Verbindung gebracht, eine strahlende Alternative zum Diamanten."
        ),
        "goshenite" to GemTranslation(
            nom = "Goshenit (weißer Beryll)",
            descriptionCourte = "Die seltene, farblose Varietät des Berylls.",
            descriptionLongue = "Kommerziell weniger gefragt als seine farbigen Verwandten (Smaragd, Aquamarin, Morganit), ist Goshenit dennoch die reinste Form des Berylls, vollständig frei von farbgebenden Elementen.",
            particularites = "Diente historisch als Material für Brillengläser, bevor optisches Glas verwendet wurde.",
            inclusions = "Der reinste Beryll der Familie; gelegentliche Hohlkanäle, sehr wenige sichtbare Einschlüsse.",
            lithotherapie = "Goshenit (farbloser Beryll) soll geistige Klarheit fördern und helfen, Situationen objektiv zu betrachten."
        ),
        "cristal-de-roche" to GemTranslation(
            nom = "Bergkristall",
            descriptionCourte = "Der reine, transparente und reichlich vorhandene Quarz.",
            descriptionLongue = "In reiner Form vollkommen farblos, ist Bergkristall einer der am häufigsten vorkommenden Edelsteine der Erde. Er wurde lange zum Schleifen von Wahrsagekugeln und optischen Linsen verwendet, bevor es industrielles Glas gab.",
            particularites = "Große Verfügbarkeit in großen Kristallen, was spektakuläre Fantasieschliffe ermöglicht.",
            inclusions = "Meist völlig rein; kann dekorative Mineraleinschlüsse (Rutil, Turmalin, Chlorit) oder Negativkristalle enthalten.",
            lithotherapie = "Als „Meisterstein\" der Lithotherapie soll Bergkristall Energien verstärken, Gedanken klären und den umgebenden Raum reinigen."
        ),
        "danburite" to GemTranslation(
            nom = "Danburit",
            descriptionCourte = "Glanz nahe dem des Topas, wenig bekannt.",
            descriptionLongue = "Im 19. Jahrhundert in Danbury (Connecticut) entdeckt, ähnelt Danburit stark dem farblosen oder blassgelben Topas, besitzt jedoch nicht dessen vollkommene Spaltbarkeit, was ihn leichter zu schleifen und im Alltag zu tragen macht.",
            particularites = "Im Gegensatz zum Topas, den er optisch oft imitiert, keine Spaltbarkeit.",
            inclusions = "Meist sehr rein; je nach burmesischer oder mexikanischer Lagerstätte seltene Flüssigkeitseinschlüsse oder akzessorische Kristalle.",
            lithotherapie = "Danburit wird mit großer Gelassenheit und der Erweckung des Herzens in Verbindung gebracht, eine sanfte Unterstützung für die Meditation."
        ),
        "bois-fossilise" to GemTranslation(
            nom = "Versteinertes Holz",
            descriptionCourte = "Baumholz, über Millionen von Jahren Atom für Atom durch Kieselsäure ersetzt.",
            descriptionLongue = "Versteinertes Holz entsteht durch die fortschreitende Verkieselung vergrabener Baumstämme, wobei Quarz die organische Substanz ersetzt und dabei die ursprüngliche Holzstruktur einschließlich der Jahresringe bewahrt. Poliert offenbart es eindrucksvolle natürliche Muster.",
            particularites = "Bewahrt die zelluläre Struktur des ursprünglichen Holzes originalgetreu, mitunter mikroskopisch sichtbar.",
            lithotherapie = "Versteinertes Holz soll tiefe Erdung bieten und an die für jede dauerhafte Veränderung nötige Geduld erinnern."
        ),
        "os-fossilise" to GemTranslation(
            nom = "Versteinerter Knochen",
            descriptionCourte = "Fossile Knochen, mitunter von Dinosauriern, mineralisiert und zu Cabochons poliert.",
            descriptionLongue = "Versteinerter Knochen, mitunter aus echten Dinosaurierknochen stammend, mineralisiert sich durch Ersetzen des organischen Apatits durch Kieselsäure oder andere Minerale, wobei die charakteristische poröse Struktur des Knochengewebes erhalten bleibt und nach dem Polieren sichtbar wird.",
            particularites = "Die ursprüngliche poröse Zellstruktur bleibt nach dem Polieren des Steins sichtbar, ein Erkennungsmerkmal fossilen Knochengewebes.",
            lithotherapie = "Versteinerter Knochen wird mit Erdung und Stabilität in Verbindung gebracht und soll an die Bedeutung von Wurzeln und persönlicher Erinnerung erinnern."
        ),
        "kornerupine" to GemTranslation(
            nom = "Kornerupin",
            descriptionCourte = "Ein seltener grünbrauner Edelstein mit starkem Pleochroismus, manchmal mit Farbwechsel.",
            descriptionLongue = "Kornerupin zeigt einen ausgeprägten Pleochroismus (je nach Betrachtungswinkel mehrere sichtbare Töne von Grün bis Rotbraun), und manche Steine aus Sri Lanka weisen sogar einen dem Alexandrit vergleichbaren Farbwechsel auf.",
            particularites = "Ausgeprägter trichroitischer Pleochroismus, mitunter begleitet von einem Farbwechsel je nach Lichtquelle.",
            inclusions = "Ausgeprägter Pleochroismus, begleitet von feinen faserigen Einschlüssen, die bei manchen Steinen einen Chatoyance-Effekt erzeugen können.",
            lithotherapie = "Kornerupin, ein unauffälliges und seltenes Mineral, wird mit sanfter Erdung und innerer Stabilität in Verbindung gebracht."
        ),
        "hyperstene" to GemTranslation(
            nom = "Hypersthen",
            descriptionCourte = "Ein schimmerndes Bronzebraun, mitunter „Samtstein\" genannt.",
            descriptionLongue = "Hypersthen zeigt einen charakteristischen bronzegoldenen Schimmer (Schiller), der auf innere lamellare Einschlüsse zurückgeht, was ihm den Beinamen „Samtstein\" einbrachte. Er wird meist als Cabochon geschliffen, um diesen Effekt zur Geltung zu bringen.",
            particularites = "Der bronzegoldene Schiller-Effekt beruht auf inneren Entmischungslamellen.",
            lithotherapie = "Hypersthen soll die Introspektion fördern und eine Form diskreten energetischen Schutzes bieten."
        ),
        "paesine" to GemTranslation(
            nom = "Paesina",
            descriptionCourte = "Ein Kalkgestein, dessen natürliche Muster an Miniaturlandschaften erinnern.",
            descriptionLongue = "Paesina, oder „pietra paesina\" (Landschaftsstein), ist ein Kalkgestein, in dem Einlagerungen von Eisen- und Manganoxiden auf natürliche Weise Muster zeichnen, die an Landschaften, Ruinen oder Horizonte erinnern – ein vollständig natürliches Bildphänomen, das in der Toskana seit der Renaissance geschätzt wird.",
            particularites = "Jede polierte Platte ist einzigartig, wie ein durch Kapillarwirkung metallischer Oxide entstandenes Naturgemälde.",
            lithotherapie = "Der als „Landschaftsstein\" bezeichnete Paesina lädt zur Kontemplation und tiefer innerer Ruhe ein."
        ),
        "enstatite" to GemTranslation(
            nom = "Enstatit",
            descriptionCourte = "Ein braun-grünes Pyroxen, gelegentlich mit Asterismus oder Katzenaugeneffekt.",
            descriptionLongue = "Enstatit, der reine magnesiumhaltige Endpunkt der Orthopyroxene, tritt in braun-grünen bis olivfarbenen Tönen auf, gelegentlich mit einem vierstrahligen Asterismus oder einem Katzenaugeneffekt, wenn er als Cabochon geschliffen wird.",
            particularites = "Kann einen vierstrahligen Asterismus zeigen, der seltener ist als der klassische sechsstrahlige Asterismus des Korunds.",
            inclusions = "Kann feine orientierte faserige Einschlüsse zeigen, die als Cabochon einen Chatoyance-Effekt erzeugen.",
            lithotherapie = "Enstatit wird mit Erdung und einer besonnenen, überlegten Handlungsfähigkeit in Verbindung gebracht."
        ),
        "sphalerite" to GemTranslation(
            nom = "Sphalerit",
            descriptionCourte = "Das Zinkerz mit der höchsten Dispersion aller geschliffenen Edelsteine.",
            descriptionLongue = "Sphalerit, das wichtigste Zinkerz, besitzt eine optische Dispersion, die unter allen facettierten Edelsteinen einen Rekordwert erreicht — höher als die des Diamanten — und spektakuläres Farbfeuer erzeugt. Seine extreme Weichheit macht ihn eher zu einem Sammlerstein als zu einem Stein für den täglichen Gebrauch.",
            particularites = "Die höchste Dispersion unter allen gängigen Sammlersteinen, die die des Diamanten übertrifft.",
            inclusions = "Sehr hohe Dispersion und diamantartiger Glanz; vollkommene Spaltbarkeit in sechs Richtungen macht sie heikel zu schleifen, mit seltenen Flüssigkeitseinschlüssen.",
            lithotherapie = "Sphalerit gilt als förderlich für die energetische Erdung und soll gleichzeitig die körperliche Vitalität anregen."
        ),
        "rutile" to GemTranslation(
            nom = "Rutil",
            descriptionCourte = "Der Kristall, der für die goldenen Einschlüsse im Rutilquarz verantwortlich ist, nur selten allein facettiert.",
            descriptionLongue = "Rutil, ein Titanoxid mit metallischem Glanz, ist vor allem als Einschlussmineral im Rutilquarz bekannt, kommt aber ausnahmsweise auch in Kristallen vor, die rein und transparent genug sind, um facettiert zu werden, wobei sie eine sehr hohe Dispersion offenbaren.",
            particularites = "Sehr hohe optische Dispersion, nahe an der des Diamanten, aufgrund seiner dunklen Farbe jedoch selten genutzt.",
            lithotherapie = "Rutil wird traditionell mit der Verstärkung von Energien und mit Klarheit beim Verfolgen eigener Ziele in Verbindung gebracht."
        ),
        "quartz-fume" to GemTranslation(
            nom = "Rauchquarz",
            descriptionCourte = "Durchscheinendes Braun, gefärbt durch natürliche Bestrahlung.",
            descriptionLongue = "Rauchquarz verdankt seinen braunen Farbton Farbzentren, die durch die natürliche Radioaktivität des umgebenden Gesteins entstehen und auf Aluminiumspuren einwirken. Er ist reichlich vorhanden und erschwinglich und wird häufig erhitzt, um in Citrin umgewandelt zu werden.",
            particularites = "Kann durch Erhitzen gelb werden (Citrin) oder bei längerer Lichteinwirkung verblassen.",
            inclusions = "Schleier feiner Flüssigkeitseinschlüsse und gelegentliche Negativkristalle, vergleichbar mit Bergkristall.",
            lithotherapie = "Rauchquarz ist bekannt für seine starken erdenden Eigenschaften, die helfen sollen, Stress und Alltagsspannungen aufzunehmen."
        ),
        "andalousite" to GemTranslation(
            nom = "Andalusit",
            descriptionCourte = "Spektakulärer grün-braun-roter Pleochroismus.",
            descriptionLongue = "Andalusit verdankt seinen Namen der spanischen Region, in der er erstmals beschrieben wurde. Sein ausgeprägter trichroitischer Pleochroismus lässt je nach Blickwinkel olivgrüne, rotbraune und gelbe Töne in ein und demselben Stein erscheinen, ein Effekt, der manchmal als „armer Alexandrit\" bezeichnet wird.",
            particularites = "Sehr ausgeprägter trichroitischer Pleochroismus, die Schliffausrichtung ist entscheidend.",
            inclusions = "Mit bloßem Auge sichtbarer starker Pleochroismus (grün, braun, rot je nach Winkel); Graphiteinschlüsse mitunter kreuzförmig angeordnet (Varietät Chiastolith).",
            lithotherapie = "Andalusit wird mit Erdung und der Fähigkeit assoziiert, angesichts von Schwierigkeiten die Perspektive zu wechseln."
        ),
        "sinhalite" to GemTranslation(
            nom = "Sinhalith",
            descriptionCourte = "Lange Zeit mit braunem Peridot verwechselt.",
            descriptionLongue = "Erst 1952 als eigenständige Art identifiziert, wurde Sinhalith zuvor irrtümlich als brauner Peridot in Museumssammlungen eingeordnet. Sein Name leitet sich von „Sinhala\", dem alten Namen Sri Lankas, seiner wichtigsten Fundstätte, ab.",
            particularites = "Bis 1952 mit Peridot verwechselt; stets braun, im Gegensatz zum grünen Peridot niemals grün.",
            inclusions = "Je nach srilankischer Lagerstätte feine Flüssigkeitseinschlüsse und akzessorische Kristalle, historisch lange mit Peridot verwechselt.",
            lithotherapie = "Sinhalith, ein seltenes und unauffälliges Mineral, wird mit innerer Stabilität und Ausdauer in Verbindung gebracht."
        ),
        "staurotide" to GemTranslation(
            nom = "Staurolith (Kreuzstein)",
            descriptionCourte = "Berühmt für seine kreuzförmigen Zwillingsbildungen.",
            descriptionLongue = "Staurolith bildet natürlicherweise kreuzförmige Zwillinge, die als „Kreuzsteine\" oder „Feensteine\" bezeichnet werden und traditionell als Amulett getragen wurden. Aufgrund seiner häufigen Opazität wird er nur selten facettiert und vor allem im rohen, verzwillingten Zustand gesammelt.",
            particularites = "Charakteristische kreuzförmige Zwillinge; wird nur selten facettiert, meist im Rohzustand gesammelt.",
            lithotherapie = "Als Kreuzstein bekannt, wird Staurolith traditionell als Talisman für Schutz und Glück getragen."
        ),
        "sphene" to GemTranslation(
            nom = "Titanit (Sphen)",
            descriptionCourte = "Die höchste Dispersion nach einigen äußerst seltenen Edelsteinen.",
            descriptionLongue = "Titanit zeigt eine optische Dispersion (das „Feuer\"), die höher ist als die des Diamanten, verbunden mit einem ausgeprägten braun-grün-gelben Pleochroismus. Seine relative Weichheit macht ihn eher zu einem Stein für Sammlungen und für Schmuckstücke, die wenig Stößen ausgesetzt sind.",
            particularites = "Außergewöhnliche Dispersion, höher als die des Diamanten; recht weich und spaltbar.",
            inclusions = "Sehr hohe Dispersion („Feuer\"), oft stärker als beim Diamanten; Wolken feiner Einschlüsse und akzessorische Kristalle häufig.",
            lithotherapie = "Titanit (Sphen) soll geistige Klarheit und Kreativität fördern und dient als Unterstützung für Projekte, die Präzision und Inspiration erfordern."
        ),
        "hematite" to GemTranslation(
            nom = "Hämatit",
            descriptionCourte = "Das grau-schwarze metallische Eisenoxid, seit der Antike spiegelglänzend poliert.",
            descriptionLongue = "Hämatit wird als Cabochon oder Intaglio geschliffen, um einen fast spiegelnden, grau-schwarzen metallischen Glanz zu offenbaren. Bereits im alten Ägypten als Siegelstein verwendet, hinterlässt sein Pulver zudem eine charakteristische blutrote Strichfarbe — daher sein Name, vom griechischen Wort für „Blut\".",
            particularites = "Sein Pulver (Strichfarbe) ist trotz des schwarzen metallischen Erscheinungsbilds blutrot, worauf sein griechischer Name zurückgeht.",
            lithotherapie = "Als Erdungsstein par excellence gilt Hämatit als Kraftspender, der innere Stärke verleihen und vor negativen Energien der Umgebung schützen soll."
        ),
        "magnetite" to GemTranslation(
            nom = "Magnetit",
            descriptionCourte = "Der natürliche Magnet der Antike, bekannt als Magnesia-Stein.",
            descriptionLongue = "Magnetit ist das schlechthin natürlich magnetische Mineral, seit der Antike als „Magnetstein\" oder Lodestone bekannt. Aufgrund seiner völligen Opazität wird er nur selten facettiert und vor allem zu Perlen und Cabochons verarbeitet.",
            particularites = "Einziges natürlich und stark magnetisches Mineral, eine Eigenschaft, die bereits in der Antike zur Navigation genutzt wurde.",
            lithotherapie = "Magnetit wird mit Erdung und energetischem Gleichgewicht in Verbindung gebracht und häufig verwendet, um Körper und Geist neu auszurichten."
        ),
        "quartz-tourmaline" to GemTranslation(
            nom = "Turmalinquarz",
            descriptionCourte = "Nadeln aus schwarzem Turmalin, eingeschlossen in klarem Quarz.",
            descriptionLongue = "Turmalinquarz schließt Nadeln aus schwarzem Turmalin (Schörl) in einem ansonsten klaren Quarzkristall ein und erzeugt so ein auffälliges grafisches Muster, das sowohl in der Lithotherapie als auch im zeitgenössischen Schmuckdesign sehr geschätzt wird.",
            particularites = "Die Turmalinnadeln bleiben mit bloßem Auge sichtbar und erzeugen bei jedem Stein ein einzigartiges grafisches Muster.",
            inclusions = "Schwarze Turmalinnadeln (Schörl), verflochten in klarem Quarz.",
            lithotherapie = "Turmalinquarz verbindet die schützenden Eigenschaften des schwarzen Turmalins mit der verstärkenden Klarheit des Bergkristalls."
        ),
        "onyx" to GemTranslation(
            nom = "Onyx",
            descriptionCourte = "Schwarze und weiße Bänder, häufig gefärbt.",
            descriptionLongue = "Als mikrokristalline Quarzvarietät aus der Familie der Chalcedone weist Onyx von Natur aus schwarze und weiße Bänder auf. Die meisten im Handel erhältlichen Steine werden gefärbt, um ein einheitliches, intensives Schwarz zu erzielen.",
            particularites = "Nahezu durchgängige künstliche Färbung zur Vereinheitlichung der Farbe.",
            lithotherapie = "Onyx wird traditionell mit innerer Kraft, emotionaler Stabilität und Schutz vor negativen Energien in Verbindung gebracht."
        ),
        "spinelle-noir" to GemTranslation(
            nom = "Schwarzer Spinell",
            descriptionCourte = "Metallischer Glanz für Herrenschmuck.",
            descriptionLongue = "Opak und von tiefem Schwarz, wird der schwarze Spinell besonders im zeitgenössischen Herrenschmuck geschätzt, wegen seines nahezu metallischen Glanzes und seiner Robustheit im täglichen Tragen.",
            particularites = "Hohe Kratzfestigkeit, geeignet für täglich getragenen Schmuck.",
            lithotherapie = "Schwarzer Spinell soll einen soliden energetischen Schutz bieten und gleichzeitig die Erdung fördern."
        ),
        "tourmaline-noire" to GemTranslation(
            nom = "Schwarzer Turmalin (Schörl)",
            descriptionCourte = "Die häufigste Turmalinvarietät.",
            descriptionLongue = "Eisenreich, ist Schörl mit Abstand die am weitesten verbreitete Turmalinvarietät der Erde. Opak und pechschwarz, wird ihm in der Lithotherapie traditionell eine schützende Wirkung zugeschrieben.",
            particularites = "Häufig gestreifte, prismatische Kristalle, mitunter von beachtlicher Größe.",
            lithotherapie = "Schwarzer Turmalin (Schörl) gilt als einer der bekanntesten Schutzsteine der Lithotherapie und soll negative Energien absorbieren sowie die Erdung stärken."
        ),
        "obsidienne" to GemTranslation(
            nom = "Obsidian",
            descriptionCourte = "Natürliches Glas mit scharfkantigem Bruch.",
            descriptionLongue = "Obsidian entsteht durch die schnelle Abkühlung kieselsäurereicher Lava und ist ein amorphes vulkanisches Glas. Sein extrem scharfer muscheliger Bruch machte ihn bereits in der Vorgeschichte zu einem bevorzugten Werkzeugmaterial, insbesondere für Pfeilspitzen und Klingen.",
            particularites = "Manche Varietäten zeigen ein goldenes oder irisierendes Schillern (Regenbogenobsidian).",
            lithotherapie = "Obsidian gilt als kraftvoller Schutzstein, der zugleich verborgene Wahrheiten offenbaren und eine tiefgreifende innere Transformation begünstigen soll."
        ),
        "rubis-etoile" to GemTranslation(
            nom = "Sternrubin",
            descriptionCourte = "Ein sechsstrahliger Stern, der über die Oberfläche des Cabochons gleitet.",
            descriptionLongue = "Der Sternrubin verdankt seinen Asterismus feinen nadelförmigen Rutileinschlüssen (der „Seide\"), die entlang der hexagonalen Symmetrie des Korunds ausgerichtet sind und das Licht zu einem beweglichen sechsstrahligen Stern reflektieren, wenn der Stein als Cabochon geschliffen wird.",
            particularites = "Der Asterismus ist nur im Cabochonschliff sichtbar, niemals im Facettenschliff, und erfordert eine punktförmige Lichtquelle.",
            inclusions = "Verdankt seinen Asterismus einem dichten Netz aus Rutilseide entlang der drei Kristallachsen; Dichte und Ausrichtung dieser Seide bestimmen die Schärfe des sechsstrahligen Sterns.",
            lithotherapie = "Sternrubin vereint die schützenden Eigenschaften des Rubins mit einer inneren Führungskraft, die durch seinen Stern symbolisiert wird."
        ),
        "saphir-etoile" to GemTranslation(
            nom = "Sternsaphir",
            descriptionCourte = "Ein leuchtender sechsstrahliger Stern, häufig in einem blauen oder schwarzen Saphir.",
            descriptionLongue = "Wie sein Verwandter, der Sternrubin, verdankt der Sternsaphir seinen Asterismus seidigen Rutileinschlüssen. Er kommt am häufigsten in Blau oder Schwarz vor, wobei Letzteres in mehreren asiatischen Kulturen traditionell mit Schutz assoziiert wird.",
            particularites = "Der begehrteste Asterismus zeigt sechs vollkommen gerade Strahlen, zentriert auf der Wölbung des Cabochons.",
            inclusions = "Dichtes Netz aus Rutilseide entlang der drei Achsen des Korunds, Ursache des im Cabochon sichtbaren sechsstrahligen Asterismus.",
            lithotherapie = "Sternsaphir soll spirituelle Führung und Schutz bringen, wobei sein Stern einen einzuschlagenden Weg symbolisiert."
        ),
        "saphir-teal" to GemTranslation(
            nom = "Teal-Saphir",
            descriptionCourte = "Ein zweifarbiger Korund, bei dem Blau und Gelb sich zu einem eigentümlichen Blaugrün verbinden.",
            descriptionLongue = "Der Teal-Saphir verdankt seine charakteristische blaugrüne Farbe dem Nebeneinander blauer (Eisen und Titan) und gelber (Eisen) Wachstumszonen innerhalb ein und desselben Kristalls, die sich nach dem Schliff optisch vermischen. Diese natürliche Zweifarbigkeit statt eines einheitlichen Farbtons macht ihn zu einem bei Liebhabern ungewöhnlicher Farben sehr gefragten Stein, insbesondere aus den Vorkommen Montanas.",
            particularites = "Die blau-gelbe Zweifarbigkeit, im Rohzustand in getrennten Zonen sichtbar, verschmilzt nach dem Schliff und der richtigen Ausrichtung zu einem einheitlichen Blaugrün.",
            inclusions = "Charakteristische blaugrüne bandförmige Farbzonierung, dezente Rutilseide, für australischen Korund typische akzessorische Kristalle.",
            lithotherapie = "Dem Teal-Saphir wird nachgesagt, das Gleichgewicht zwischen Vernunft und Intuition zu fördern, wobei seine doppelte Färbung die Harmonie zweier sich ergänzender Energien symbolisiert."
        ),
        "diaspore-zultanite" to GemTranslation(
            nom = "Zultanit",
            descriptionCourte = "Ein Farbwechsel von Khakigrün zu Champagnerrosa aus einem einzigartigen Vorkommen in der Türkei.",
            descriptionLongue = "Unter dem Namen „Zultanit\" vermarktet, wechselt diese Diaspor-Varietät die Farbe von olivfarbenem Khakigrün bei Tageslicht zu Champagnerrosa bis Violett bei Glühlicht und stammt aus einem einzigen Vorkommen in den türkischen Bergen.",
            particularites = "Weltweit nahezu einzigartiges Vorkommen; der Farbwechsel ist subtiler als der des Alexandrits.",
            inclusions = "Ausgeprägter Pleochroismus (Grün, Gelb, Champagnerrosa je nach Beleuchtung); feine Flüssigkeitseinschlüsse und vollkommene Spaltbarkeit, die den Schliff heikel machen.",
            lithotherapie = "Zultanit, das je nach Licht die Farbe wechselt, wird mit Anpassungsfähigkeit und der Fähigkeit zur persönlichen Wandlung in Verbindung gebracht."
        ),
        "ametrine" to GemTranslation(
            nom = "Ametrin",
            descriptionCourte = "Ein zweifarbiger Quarz, bei dem sich das Violett des Amethysts und das Gelb des Citrins denselben Kristall teilen.",
            descriptionLongue = "Ametrin verdankt seine Zweifarbigkeit einem natürlichen Temperaturgefälle innerhalb des Quarzkristalls während seines Wachstums: Die wärmeren Zonen nahmen den gelben Farbton des Citrins an, während die kühleren Zonen das Violett des Amethysts bewahrten. Die bolivianische Anahí-Mine, lange Zeit die einzige kommerzielle Quelle weltweit, ist mit einer Legende aus dem 17. Jahrhundert verbunden, wonach ein spanischer Konquistador, der eine einheimische Prinzessin und Eigentümerin der Lagerstätte heiratete, sie entdeckt haben soll.",
            particularites = "Der Schliff wird so gewählt, dass der klare Kontrast zwischen den beiden Farbzonen betont wird, die oft diagonal verlaufen.",
            inclusions = "Scharfe Zonierung zwischen violetten und gelben Sektoren, geerbt von der Kristallstruktur des Quarzes, mit den für die Spezies typischen Flüssigkeitseinschlüssen.",
            lithotherapie = "Ametrin soll die beruhigenden Eigenschaften des Amethysts mit den anregenden Eigenschaften des Citrins vereinen — ein Gleichgewicht zwischen innerer Ruhe und schöpferischer Energie."
        ),
        "grenat-couleur-changeante" to GemTranslation(
            nom = "Farbwechsel-Granat",
            descriptionCourte = "Tagsüber blaugrün, abends rotviolett — ein wenig bekannter Rivale des Alexandrits.",
            descriptionLongue = "Manche Pyrop-Spessartin-Granate aus Ostafrika zeigen einen spektakulären Farbwechsel von blaugrün oder graugrün bei Tageslicht zu rotviolett bei Glühlicht, ein unter Granaten seltenes Phänomen.",
            particularites = "Für den Farbwechsel in diesem Granat ist Vanadium verantwortlich, nicht Chrom.",
            inclusions = "Akzessorische Kristalle und feine Fasern, typisch für den Pyrop-Spessartin-Granat, dessen intermediäre Zusammensetzung er teilt.",
            lithotherapie = "Dieser Farbwechsel-Granat symbolisiert Anpassungsfähigkeit und die Fähigkeit, sich angesichts wechselnder Umstände zu erneuern."
        ),
        "pietersite" to GemTranslation(
            nom = "Pietersit",
            descriptionCourte = "Ein schillernder blau-goldener Wirbel, genannt „Auge des Sturms\".",
            descriptionLongue = "Pietersit ist ein Quarz mit faserigen Einschlüssen von zerbrochenem und wieder verkittetem Krokydolith, der ein chaotisches blaues, goldenes und braunes Schillern erzeugt, das an einen erstarrten Sturm erinnert — daher sein Beiname „Auge des Sturms\". Entdeckt 1962 in Namibia.",
            particularites = "Das chaotische Schillermuster entsteht, anders als beim regelmäßigen Tigerauge, durch eine natürliche Zerbrechung der inneren Fasern.",
            lithotherapie = "Als „Sturmstein\" bekannt, soll Pietersit Mut angesichts schneller und unvorhergesehener Veränderungen unterstützen."
        ),
        "agate" to GemTranslation(
            nom = "Achat",
            descriptionCourte = "Die berühmteste farbige konzentrische Bänderung des Quarzes.",
            descriptionLongue = "Achat ist ein Chalcedon mit konzentrischen oder parallelen Bändern in verschiedenen Farben, die durch aufeinanderfolgende Kieselsäureablagerungen in vulkanischen Hohlräumen entstehen. Seine zahllosen Varietäten (Moos-, Dendriten-, Landschafts-, Augenachat...) machen ihn zu einem der weltweit meistgesammelten Schmucksteine.",
            particularites = "Die Bänderung wird häufig durch Färbung hervorgehoben, eine alte und am Markt weithin akzeptierte Praxis.",
            lithotherapie = "Achat wird traditionell mit emotionalem Gleichgewicht, Stabilität und einem sanften alltäglichen Schutz in Verbindung gebracht."
        ),
        "jaspe" to GemTranslation(
            nom = "Jaspis",
            descriptionCourte = "Ein opaker Quarz mit unendlich vielfältigen Mustern, von Blutrot bis Landschaftsgrün.",
            descriptionLongue = "Jaspis ist ein mikrokristallines Quarzaggregat, das durch zahlreiche mineralische Verunreinigungen opak wird und eine nahezu unendliche Palette an Farben und Mustern bietet. Der „Landschaftsjaspis\" bildet ganze Naturszenen im polierten Stein nach.",
            particularites = "Vollständige Opazität im Gegensatz zum Achat, bedingt durch die Dichte der eingeschlossenen mineralischen Verunreinigungen.",
            lithotherapie = "Jaspis soll Erdung und Ausdauer fördern und als Unterstützung dienen, um in anspruchsvollen Phasen durchzuhalten."
        ),
        "calcedoine" to GemTranslation(
            nom = "Chalcedon",
            descriptionCourte = "Die mikrokristalline Form des Quarzes, Grundlage von Achat, Karneol und Onyx.",
            descriptionLongue = "Chalcedon ist die kryptokristalline (mit bloßem Auge unsichtbare Mikrokristalle) Form des Quarzes, aus der sich Achat, Karneol, Chrysopras und Onyx ableiten. Die durchscheinende blaugraue Varietät, „blauer Chalcedon\" genannt, ist im Schmuckbereich am begehrtesten.",
            particularites = "Oberbegriff für mikrokristallinen Quarz; Achat, Karneol und Onyx sind benannte Varietäten davon.",
            inclusions = "Faserige mikrokristalline Struktur, verantwortlich für die milchige Durchscheinung; wenige einzeln sichtbare Einschlüsse.",
            lithotherapie = "Chalcedon wird mit innerer Harmonie und einer entspannten Kommunikation mit dem eigenen Umfeld in Verbindung gebracht."
        ),
        "quartz-a-inclusions" to GemTranslation(
            nom = "Einschlussquarz (Gartenquarz)",
            descriptionCourte = "Eine mineralische Miniaturlandschaft, eingeschlossen in einem klaren Kristall.",
            descriptionLongue = "Zahlreiche Varietäten von klarem Quarz enthalten Einschlüsse anderer Minerale — je nach Fundort Chlorit, Aktinolith, Hämatit, Rutil, Lithiophilit, Fuchsit oder Pyrit — und schaffen so einzigartige innere Landschaften, die als „Gartenquarz\" (Lodolith) oder Phantomquarz bezeichnet werden.",
            particularites = "Jeder Stein ist je nach Art des eingeschlossenen Minerals einzigartig; niemals gibt es zwei identische Einschlussquarze.",
            inclusions = "Enthält per Definition vielfältige und reichliche Mineraleinschlüsse — Chlorit, Aktinolith, Hämatit, Rutil, Lithiophilit oder Fuchsit je nach Lagerstätte — die einzigartige innere Landschaften schaffen (einen „Garten\").",
            lithotherapie = "Einschlussquarz (der sogenannte „Gartenquarz\") lädt zur Introspektion ein, wobei jeder Einschluss eine Facette der inneren Welt symbolisiert."
        ),
        "quartz-rutile" to GemTranslation(
            nom = "Rutilquarz",
            descriptionCourte = "Goldene „Venushaare\", eingeschlossen in klarem Bergkristall.",
            descriptionLongue = "Rutilquarz schließt feine goldene Rutilnadeln ein, poetisch als „Venushaare\" oder „Liebespfeile\" bezeichnet, und erzeugt so einen auffälligen dekorativen Effekt, der im zeitgenössischen Schmuck sehr gefragt ist.",
            particularites = "Die Rutileinschlüsse können auch einen Katzenaugeneffekt erzeugen, wenn der Kristall als Cabochon geschliffen wird.",
            inclusions = "Goldene oder kupferfarbene Rutilnadeln, die den Kristall durchziehen, mitunter büschel- oder sternförmig angeordnet.",
            lithotherapie = "Rutilquarz verbindet die verstärkenden Eigenschaften des Bergkristalls mit einer gestärkten Schutzwirkung."
        ),
        "quartz-super-sept" to GemTranslation(
            nom = "Super-Sieben-Quarz",
            descriptionCourte = "Bis zu sieben Minerale vereint in einem einzigen brasilianischen Amethystkristall.",
            descriptionLongue = "Der „Super Seven\" (oder Melody-Stein) ist ein amethystfarbener Quarz aus Brasilien, der bis zu sieben verschiedene Minerale als Einschlüsse enthält — unter anderem Cacoxenit, Goethit, Lepidokrokit, Rutil und Hämatit — und dadurch bei jedem Stein einzigartige goldene und violette Muster erzeugt.",
            particularites = "Weltweit einzigartiges Vorkommen; der Handelsname bezieht sich auf die sieben möglicherweise enthaltenen Minerale.",
            inclusions = "Charakteristische Vereinigung von sieben eingeschlossenen Mineralien (Amethyst, Cacoxenit, Rutil, Goethit, Lepidokrokit, Limonit, Hämatit), einzigartig für die brasilianische Lagerstätte Bahia.",
            lithotherapie = "Als seltene Vereinigung von sieben Mineralen soll Super-Sieben-Quarz eine tiefe Meditation und eine Form spiritueller Synthese fördern."
        ),
        "smithsonite" to GemTranslation(
            nom = "Smithsonit",
            descriptionCourte = "Traubige „Bonbon\"-Aggregate in einer breiten Pastellpalette.",
            descriptionLongue = "Smithsonit bildet traubige (botryoidale) Massen in sehr unterschiedlichen Pastelltönen — je nach vorhandenen Metallspuren rosa, blau, grün, gelb oder mauve — deren seidige, gerundete Oberfläche an Bonbons erinnert und die als Cabochon sehr geschätzt wird.",
            particularites = "Die Farbe variiert je nach Spurenmetall: Kupfer (blaugrün), Kobalt (rosa), Cadmium (gelb).",
            inclusions = "Tritt meist als durchscheinende traubenförmige Aggregate in Pastelltönen auf; feinkörnige innere Struktur.",
            lithotherapie = "Smithsonit wird mit Sanftheit und emotionaler Beruhigung in Verbindung gebracht, als Unterstützung, um Reizbarkeit zu besänftigen."
        ),
        "moldavite" to GemTranslation(
            nom = "Moldavit",
            descriptionCourte = "Ein olivgrünes Glas, entstanden vor 15 Millionen Jahren durch einen Meteoriteneinschlag.",
            descriptionLongue = "Moldavit ist ein natürliches Glas, das durch die augenblickliche Schmelze irdischen Gesteins beim Einschlag eines Meteoriten in Bayern vor etwa 15 Millionen Jahren entstand, wobei geschmolzene Glaströpfchen bis nach Böhmen geschleudert wurden, wo man ihn heute findet.",
            particularites = "Geografisch weltweit einzigartiges Vorkommen, verbunden mit dem Einschlagskrater des Nördlinger Ries in Bayern (Deutschland).",
            inclusions = "Ein natürliches Glas meteoritischen Ursprungs, das typischerweise längliche Gasblasen und Fäden aus geschmolzener Kieselsäure (Lechatelierit) enthält.",
            lithotherapie = "Aufgrund seines meteoritischen Ursprungs soll Moldavit eine intensive innere Transformation und ein beschleunigtes spirituelles Erwachen bewirken."
        ),
        "verre-libyque" to GemTranslation(
            nom = "Libysches Wüstenglas",
            descriptionCourte = "Ein durchscheinendes gelbes Wüstenglas, enthalten im Brustschmuck Tutanchamuns.",
            descriptionLongue = "Libysches Wüstenglas ist ein blassgelbes bis gelbgrünes natürliches Glas, das vor 29 Millionen Jahren in der libyschen Wüste durch einen Meteoriteneinschlag oder eine Luftexplosion entstand. Ein aus diesem Glas geschnittener Skarabäus schmückt das Grabpektorale Tutanchamuns.",
            particularites = "Wurde bereits von altägyptischen Handwerkern vor über 3.000 Jahren verwendet, lange vor seiner modernen wissenschaftlichen Beschreibung.",
            inclusions = "Ein natürliches Glas meteoritischen/tektitischen Ursprungs mit Gasblasen und mitunter feinen Zirkon- oder Baddeleyit-Einschlüssen.",
            lithotherapie = "Vor Millionen von Jahren durch einen Meteoriteneinschlag entstanden, wird libysches Wüstenglas mit geistiger Klarheit und einem symbolischen Sonnenschutz in Verbindung gebracht."
        ),
        "alexandrite" to GemTranslation(
            nom = "Alexandrit",
            descriptionCourte = "Tagsüber grün, unter Glühlicht rot.",
            descriptionLongue = "Im 19. Jahrhundert im Ural entdeckt und zu Ehren des zukünftigen Zaren Alexander II. benannt, wechselt Alexandrit auf spektakuläre Weise die Farbe: smaragdgrün bei Tageslicht, purpurrot unter Glühlicht. Steine mit ausgeprägtem Farbwechsel sind äußerst selten und begehrt.",
            particularites = "Der Grad des Farbwechsels ist das wichtigste Wertkriterium.",
            inclusions = "Feine Flüssigkeitseinschlüsse und akzessorische Kristalle; wie beim klassischen Chrysoberyll können zyklische Zwillinge in Form eines dreistrahligen Sterns auftreten.",
            lithotherapie = "Alexandrit, der je nach Licht die Farbe wechselt, soll Anpassungsfähigkeit und das Gleichgewicht zwischen Verstand und Intuition fördern."
        ),
        "tourmaline-pasteque" to GemTranslation(
            nom = "Wassermelonenturmalin",
            descriptionCourte = "Rosafarbener Kern, umgeben von Grün, wie eine Fruchtscheibe.",
            descriptionLongue = "Als Ergebnis eines mehrstufigen chemischen Kristallwachstums zeigt der Wassermelonenturmalin einen rosafarbenen Kern, umgeben von einer grünen Schicht, der in dünne Scheiben geschnitten wird, um dieses eindrucksvolle natürliche Muster zu offenbaren.",
            particularites = "Wird meist in Querscheiben geschnitten, um den „Wassermelonen\"-Effekt zu zeigen.",
            inclusions = "Scharfe Farbzonierung zwischen rosa Kern und grünem Rand, mit den für Turmalin typischen Trichiten und Hohlkanälen.",
            lithotherapie = "Wassermelonenturmalin verbindet die beruhigenden Eigenschaften des Rosa mit der schützenden Energie des Grün und symbolisiert das Gleichgewicht zwischen Herz und Handeln."
        ),
        "labradorite" to GemTranslation(
            nom = "Labradorit",
            descriptionCourte = "Bewegliche metallische Reflexe (Labradoreszenz).",
            descriptionLongue = "Labradorit zeigt ein optisches Phänomen namens Labradoreszenz: blaugrüne, manchmal goldene oder violette Glanzlichter erscheinen und verschwinden je nach Betrachtungswinkel, verursacht durch innere Lamellen, die das Licht beugen.",
            particularites = "Die Ausrichtung des Schliffs ist entscheidend, um die Labradoreszenz zu offenbaren.",
            inclusions = "Entmischungslamellen, verantwortlich für den schillernden Glanz (Labradoreszenz), mitunter begleitet von feinen Ilmenit- oder Magnetit-Einschlüssen.",
            lithotherapie = "Labradorit soll einen starken energetischen Schutz bieten und gleichzeitig Intuition und die Magie des Alltags anregen."
        ),
        "pierre-de-lune" to GemTranslation(
            nom = "Mondstein",
            descriptionCourte = "Schwebender bläulicher Schimmer (Adulareszenz).",
            descriptionLongue = "Mondstein verdankt seinen Namen dem schwebenden bläulichen Schimmer, der Adulareszenz, verursacht durch das mikroskopisch feine Verwachsen zweier Feldspäte, die das Licht beugen. Die besten kräftig blauen Qualitäten stammen aus Sri Lanka.",
            particularites = "Optimale Adulareszenz, wenn der Stein senkrecht zu den inneren Lamellen als Cabochon geschliffen wird.",
            inclusions = "Albit-Orthoklas-Entmischungslamellen, verantwortlich für die Adulareszenz, jenen bläulichen Schimmer, der unter der Oberfläche zu schweben scheint.",
            lithotherapie = "Mondstein wird traditionell mit Intuition, Sensibilität und Neuanfängen in Verbindung gebracht, verknüpft mit den Mondzyklen."
        ),
        "pierre-de-soleil" to GemTranslation(
            nom = "Sonnenstein",
            descriptionCourte = "Kupferfarbenes Glitzern durch Kupfereinschlüsse.",
            descriptionLongue = "Im Gegensatz zum Mondstein verdankt der Sonnenstein sein warmes Glitzern (Aventureszenz) feinen Kupfer- oder Hämatitplättchen im Kristall, die je nach Beleuchtung orangefarbene bis kupferrote Reflexe erzeugen.",
            particularites = "Aventureszenz durch Plättchen aus gediegenem Kupfer, im Gegensatz zum durch Fuchsit gefärbten Aventurin-Quarz.",
            inclusions = "Hämatit- oder Goethit-Plättchen als flache, orientierte Einschlüsse, verantwortlich für das charakteristische Funkeln (Aventureszenz).",
            lithotherapie = "Sonnenstein soll Lebensfreude, Vitalität und Selbstvertrauen bringen, ganz im Bild seines warmen Glanzes."
        ),
        "fluorine" to GemTranslation(
            nom = "Fluorit",
            descriptionCourte = "Die breiteste Farbpalette im gesamten Mineralreich.",
            descriptionLongue = "Fluorit kann in nahezu jeder Farbe vorkommen, manchmal sogar mehrfarbig in einem einzigen zonierten Kristall. Seine Weichheit und seine perfekte Spaltbarkeit in vier Richtungen schränken seine Verwendung im Schmuckbereich ein, machen ihn aber zu einem äußerst geschätzten Sammlerstein.",
            particularites = "Perfekte Spaltbarkeit in vier Richtungen; charakteristische Fluoreszenz unter UV-Licht, auf die der Begriff „Fluoreszenz\" zurückgeht.",
            inclusions = "Mitunter sichtbare bandförmige Farbzonierung, feine Flüssigkeitseinschlüsse; vollkommene Spaltbarkeit in vier Richtungen macht den Stein als Schmuckstück zerbrechlich.",
            lithotherapie = "Fluorit wird häufig verwendet, um Konzentration und geistige Klarheit zu fördern, insbesondere in Lern- oder intensiven Arbeitsphasen."
        ),
        "ammolite" to GemTranslation(
            nom = "Ammolith",
            descriptionCourte = "Die erstarrte Irisierung fossiler Ammonitenschalen.",
            descriptionLongue = "Ammolith stammt aus dem fossilen Perlmutt 70 Millionen Jahre alter Ammonitenschalen, die fast ausschließlich entlang der kanadischen Rocky Mountains gefunden werden. Er zeigt eine vielfarbige Irisierung, vergleichbar mit der des Opals, einzigartig unter den organischen Edelsteinen.",
            particularites = "Organischer fossiler Edelstein; nahezu geografisches Monopol im Süden Albertas.",
            lithotherapie = "Ammolith, ein organischer fossiler Edelstein, wird mit Glück, Vitalität und positiver Transformation in Verbindung gebracht."
        ),
        "corail" to GemTranslation(
            nom = "Rote Koralle",
            descriptionCourte = "Das kalkige Skelett eines Meerestiers, seit der Antike ein kostbares Blutrot.",
            descriptionLongue = "Die kostbare rote Koralle ist das verzweigte Kalkskelett eines kleinen, koloniebildenden Meerestiers (Corallium rubrum), das seit der Antike im Mittelmeer geerntet wird. Ihre Übernutzung hat sie heute zu einem streng regulierten organischen Edelstein gemacht.",
            particularites = "Streng regulierte Ernte (CITES für bestimmte Arten) aufgrund der historischen Übernutzung der Riffe.",
            lithotherapie = "Rote Koralle wird traditionell als Schutz getragen, insbesondere für Kinder, und mit Vitalität und familiärer Energie in Verbindung gebracht."
        ),
        "perle-conque" to GemTranslation(
            nom = "Conch-Perle (Lambi)",
            descriptionCourte = "Eine flammenrosafarbene Perle ohne Perlmutt, aus der karibischen Fechterschnecke.",
            descriptionLongue = "Die Conch-Perle, auch Lambi-Perle genannt, entsteht in der Königs-Fechterschnecke (Strombus gigas) der Karibik. Im Gegensatz zu klassischen Perlmuttperlen ist sie perlmuttfrei und verdankt ihren seidigen Glanz sowie ihr charakteristisches „Flammen\"-Muster der faserigen Struktur des Aragonits.",
            particularites = "An der Oberfläche sichtbare „Flammen\"-Struktur, einzigartig bei perlmuttfreien Perlen wie der Conch-Perle oder der Melo-Perle.",
            lithotherapie = "Die Conch-Perle wird mit Weiblichkeit, Intuition und emotionaler Sanftheit in Verbindung gebracht."
        ),
        "ambre" to GemTranslation(
            nom = "Bernstein",
            descriptionCourte = "Baumharz, das seit Millionen von Jahren fossilisiert ist.",
            descriptionLongue = "Bernstein ist über Millionen von Jahren fossilisiertes Harz von Nadel- oder Laubbäumen. Seine charakteristische Leichtigkeit und seine mitunter spektakulären Einschlüsse (Insekten, Pflanzen) machten ihn bereits in der Vorgeschichte zu einem kostbaren Material, insbesondere entlang der baltischen „Bernsteinstraße\".",
            particularites = "Schwimmt in Salzwasser; kann sehr begehrte fossile Einschlüsse (Insekten, Pflanzen) enthalten.",
            inclusions = "Kann spektakuläre fossile Einschlüsse enthalten — Insekten, Pflanzenreste, Luftblasen —, echte Fenster in längst vergangene Ökosysteme, besonders geschätzt von der Baltischen Bernsteinstraße.",
            lithotherapie = "Bernstein gilt seit der Antike als beruhigend und schützend und soll Wärme sowie emotionalen Trost spenden."
        ),
        "perle" to GemTranslation(
            nom = "Zuchtperle",
            descriptionCourte = "Der einzige Edelstein, der von einem Lebewesen hervorgebracht wird.",
            descriptionLongue = "Von einer Muschel als Reaktion auf einen Fremdkörper gebildet, besteht die Perle aus konzentrischen Perlmuttschichten. Nahezu alle heute im Handel erhältlichen Perlen sind Zuchtperlen (Akoya, Tahiti, Südsee), wobei sich der menschliche Eingriff auf das Einsetzen des ursprünglichen Nukleus beschränkt.",
            particularites = "Der Preis wird pro Stück oder pro Strang je nach Größe, Form, Lüster und Herkunft bewertet, nicht pro Karat.",
            inclusions = "Konzentrisch geschichtete Perlmuttstruktur, bei feinen Perlen mitunter durchscheinend sichtbar; für jede Perle einzigartige Wachstumsunregelmäßigkeiten als Zeichen ihrer natürlichen oder gezüchteten Echtheit.",
            lithotherapie = "Die Zuchtperle wird mit Reinheit, Weisheit und Harmonie in zwischenmenschlichen Beziehungen in Verbindung gebracht."
        ),
        "aventurine" to GemTranslation(
            nom = "Grüner Aventurin",
            descriptionCourte = "Ein glitzernder grüner Quarz, durchsetzt mit Fuchsit-Flittern.",
            descriptionLongue = "Der Aventurin verdankt seinen Namen und sein charakteristisches Glitzern (Aventureszenz) feinen Einschlüssen von chromhaltigem Glimmer (Fuchsit) oder Hämatit, die in einer mikrokristallinen Quarzmasse verteilt sind. Die grüne Varietät, die am weitesten verbreitete, wird seit Jahrhunderten in großen Mengen in Indien abgebaut.",
            particularites = "Die Aventureszenz, dieses metallische Glitzern, entsteht durch die Reflexion des Lichts an den eingeschlossenen Glimmerplättchen; der Begriff wurde später auch für künstliches Glas übernommen, das diesen Effekt nachahmt.",
            inclusions = "Im Quarz verteilte Fuchsit-Plättchen (chromhaltiger Glimmer), verantwortlich für das charakteristische Funkeln (Aventureszenz).",
            lithotherapie = "Der grüne Aventurin gilt als Glücksbringer und wird mit Glück, Fülle und emotionaler Beruhigung in Verbindung gebracht."
        ),
        "epidote" to GemTranslation(
            nom = "Epidot",
            descriptionCourte = "Ein charakteristisches Pistaziengrün, wegen seines ausgeprägten Pleochroismus nur selten facettiert.",
            descriptionLongue = "Epidot gibt einer ganzen Mineralgruppe seinen Namen und tritt in länglichen Kristallen von pistazien- bis olivgrüner Farbe auf, die von Eisen herrührt. Sein starker Pleochroismus, der je nach Betrachtungswinkel unterschiedliche Farbtöne zeigt, erschwert den Schliff von Steinen mit gleichmäßiger Farbe.",
            particularites = "Der starke Pleochroismus (grün, gelbbraun, rosafarben-farblos je nach Winkel) muss beim Schliff berücksichtigt werden, um die schönste Farbfläche zur Geltung zu bringen.",
            inclusions = "Ausgeprägter Pleochroismus und je nach Lagerstätte feine faserige Einschlüsse oder akzessorische Kristalle.",
            lithotherapie = "Epidot soll die persönliche Transformation fördern und dabei helfen, sich von wiederkehrenden emotionalen Mustern zu befreien."
        ),
        "gaspeite" to GemTranslation(
            nom = "Gaspeit",
            descriptionCourte = "Ein opakes apfelgrünes Nickelcarbonat, selten und als Cabochon begehrt.",
            descriptionLongue = "Gaspeit ist ein opakes Nickelcarbonat von apfel- bis leuchtend grüner Farbe, entdeckt auf der Gaspésie-Halbinsel in Québec, die ihm ihren Namen gab. Die abbauwürdigen australischen Vorkommen in Schmuckqualität sind heute die wichtigste kommerzielle Quelle.",
            particularites = "Wird aus der Ferne wegen ihrer opaken grünen Farbe oft mit Türkis oder Variszit verwechselt, unterscheidet sich aber durch ihren deutlicheren apfelgrünen Farbton.",
            lithotherapie = "Gaspeit wird mit Fülle und sanfter Erdung assoziiert und soll Stabilität in Zeiten des Wandels fördern."
        ),
        "hiddenite" to GemTranslation(
            nom = "Hiddenit",
            descriptionCourte = "Die grüne, chromgefärbte Varietät des Spodumens, eng verwandt mit dem Kunzit.",
            descriptionLongue = "Hiddenit ist die grüne Varietät des Spodumens, deren Farbe von Chrom- oder Vanadiumspuren herrührt – im Gegensatz zum rosafarbenen Kunzit, der seine Farbe Mangan verdankt. Ende des 19. Jahrhunderts in North Carolina entdeckt, bleibt das beste Material nach wie vor amerikanisch, obwohl auch Brasilien und Afghanistan es fördern.",
            particularites = "Wie alle Spodumen-Varietäten besitzt er eine vollkommene Spaltbarkeit in zwei Richtungen und muss mit größter Sorgfalt geschliffen werden.",
            inclusions = "Feine Flüssigkeitseinschlüsse und vollkommene Spaltbarkeit in zwei Richtungen, wie beim Kunzit, mit dem sie die Spezies (Spodumen) teilt.",
            lithotherapie = "Hiddenit soll das Herz für Mitgefühl öffnen und zugleich Klarheit und Urteilsvermögen bei wichtigen Entscheidungen schenken."
        ),
        "angelite" to GemTranslation(
            nom = "Angelit",
            descriptionCourte = "Die himmelblaue Varietät des Anhydrits, in der Lithotherapie sehr geschätzt.",
            descriptionLongue = "Angelit ist die Handelsbezeichnung für blassblauen, milchigen Anhydrit, der zu Cabochons, Perlen oder Dekorstücken poliert wird. Seine Farbe stammt von Spurenverunreinigungen im wasserfreien Calciumsulfat, das entsteht, wenn Gips über lange geologische Zeiträume komprimiert wird und sein Wasser verliert.",
            particularites = "Verkratzt leicht und ist empfindlich gegenüber anhaltender Feuchtigkeit, die ihn langsam zu Gips hydratisieren kann; vor Wasser und Stößen zu schützen.",
            lithotherapie = "Angelit wird mit Kommunikation, Gelassenheit und einer Form ruhiger spiritueller Verbindung assoziiert, worauf sein sprechender Name anspielt."
        ),
        "oeil-de-faucon" to GemTranslation(
            nom = "Falkenauge",
            descriptionCourte = "Die schillernde blaugraue, nicht oxidierte Variante des Tigerauges.",
            descriptionLongue = "Das Falkenauge hat denselben Ursprung wie das Tigerauge: eine Pseudomorphose von Quarz nach Krokydolith (Blauasbest), dessen parallele Fasern einen seidigen Schimmer erzeugen. Im Gegensatz zum goldenen Tigerauge behält es den ursprünglichen blaugrauen bis blaugrünen Farbton bei, da hier keine Eisenoxidation stattgefunden hat.",
            particularites = "Ein und derselbe Rohblock kann örtlich sowohl blaugraue Zonen (Falkenauge) als auch goldene Zonen (Tigerauge) aufweisen, je nach Grad der Eisenoxidation.",
            lithotherapie = "Das Falkenauge wird traditionell mit Hellsicht, innerer Klarheit und der Fähigkeit assoziiert, in komplexen Situationen Abstand zu gewinnen."
        ),
        "howlite" to GemTranslation(
            nom = "Howlith",
            descriptionCourte = "Ein weißer, grau geäderter Stein, der oft gefärbt wird, um Türkis nachzuahmen.",
            descriptionLongue = "Howlith kommt natürlich in weißen, porösen Knollen vor, durchzogen von grauen bis schwarzen Adern, die an eine Marmorierung erinnern. Seine Porosität macht ihn leicht färbbar, weshalb er das am häufigsten verwendete Material ist, um Türkis kostengünstig zu imitieren – eine Praxis, die vor dem Kauf stets zu prüfen ist.",
            particularites = "Seine hohe Porosität macht ihn besonders aufnahmefähig für Farbstoffe, was auf dem Markt zu zahlreichen Türkis- oder Lapislazuli-Imitationen geführt hat.",
            lithotherapie = "Howlith soll einen unruhigen Geist beruhigen und einen erholsameren Schlaf fördern."
        ),
        "rhodizite" to GemTranslation(
            nom = "Rhodizit",
            descriptionCourte = "Ein extrem seltenes Borat, eines der härtesten Minerale nach dem Korund.",
            descriptionLongue = "Rhodizit ist ein komplexes Borat aus Caesium, Beryllium und Aluminium, das in winzigen, farblosen bis blassgelben Kristallen fast ausschließlich auf Madagaskar kristallisiert. Seine außergewöhnliche Härte, die der des Korunds nahekommt, und seine extreme Seltenheit machen ihn zu einem Stein, der fast ausschließlich für erfahrene Sammler bestimmt ist.",
            particularites = "Facettierbare Kristalle über einem Karat sind außergewöhnlich selten; die meisten geschliffenen Steine wiegen weniger als 0,5 Karat.",
            inclusions = "Eine sehr seltene Spezies, die als kleine dodekaedrische Kristalle auftritt; innere Einschlüsse wenig dokumentiert.",
            lithotherapie = "Rhodizit wird mit energetischer Harmonisierung und der Verstärkung positiver Absichten assoziiert."
        ),
        "sanidine" to GemTranslation(
            nom = "Sanidin",
            descriptionCourte = "Ein farbloser bis blassgelber vulkanischer Feldspat, der rasch nahe der Oberfläche auskristallisiert.",
            descriptionLongue = "Sanidin ist die Hochtemperaturform des Kalifeldspats, der rasch in vulkanischem Gestein und Lava kristallisiert, im Unterschied zum langsamer in der Tiefe gebildeten Orthoklas. Die begehrtesten klaren, facettierbaren Kristalle stammen aus vulkanischen Auswürflingen der Eifel in Deutschland.",
            particularites = "Unterscheidet sich vom Orthoklas durch seine rasche vulkanische Entstehung und seine ungeordnetere Atomstruktur; beide teilen dieselbe chemische Formel.",
            inclusions = "Meist rein, mit je nach vulkanischer Herkunftslagerstätte seltenen akzessorischen kristallinen Einschlüssen.",
            lithotherapie = "Sanidin wird mit geistiger Klarheit und Spontaneität assoziiert, im Einklang mit seiner raschen Entstehung im vulkanischen Gestein."
        ),
        "tremolite" to GemTranslation(
            nom = "Tremolit",
            descriptionCourte = "Ein weißes bis graues Amphibol, dessen rosafarbene Varietät weitaus begehrter ist.",
            descriptionLongue = "Tremolit ist ein calcium-magnesiumhaltiges Amphibol, das den magnesiumreichen Endpunkt der Tremolit-Aktinolith-Reihe bildet; in kompakter, faseriger Form ist es einer der Bestandteile des Nephrits. Seine Edelsteinvarietät, meist weiß, grau oder farblos, wird selten facettiert – eine Ausnahme bildet die seltene violette Varietät namens Hexagonit.",
            particularites = "Die äußerst seltene rosaviolette Varietät Hexagonit verdankt ihre Farbe Mangan und wird vor einer Analyse mitunter mit Tansanit verwechselt.",
            inclusions = "Charakteristische faserige Struktur, oft verantwortlich für einen Chatoyance-Effekt bei Cabochon-Steinen.",
            lithotherapie = "Tremolit soll Sanftheit und Flexibilität gegenüber Veränderungen schenken, im Einklang mit seiner faserigen Struktur."
        ),
        "oeil-de-taureau" to GemTranslation(
            nom = "Stierauge",
            descriptionCourte = "Erhitztes Tigerauge, dessen Eisenoxidation in ein tiefes Rotbraun übergeht.",
            descriptionLongue = "Das Stierauge entsteht durch kontrolliertes Erhitzen von goldenem Tigerauge, eine Behandlung, die die Eisenoxidation verstärkt und den Farbton von Gelbbraun zu einem tiefen, kräftigen Rotbraun verändert, während der charakteristische seidige Schimmer der Faserstruktur erhalten bleibt.",
            particularites = "Die thermische Behandlung, die diesen rotbraunen Farbton erzeugt, ist im Handel üblich und weithin akzeptiert, sofern sie offengelegt wird.",
            lithotherapie = "Das Stierauge wird mit Kraft, Erdung und Entschlossenheit assoziiert, in symbolischer Fortführung des Tigerauges."
        ),
        "unakite" to GemTranslation(
            nom = "Unakit",
            descriptionCourte = "Ein grün-rosa gesprenkeltes Gestein, eine Mischung aus verwittertem Granit.",
            descriptionLongue = "Unakit ist ein verwittertes granitisches Gestein, das aus einer charakteristischen Mischung von rosafarbenem Feldspat, grünem Epidot und Quarz besteht, was ihm ein sofort erkennbares gesprenkeltes Muster verleiht. Benannt nach den Unaka Mountains in North Carolina, wo es erstmals beschrieben wurde, wird es vor allem zu Cabochons und Perlen verarbeitet.",
            particularites = "Da es sich um ein Mischgestein und nicht um ein einzelnes Mineral handelt, variieren seine Härte und sein Brechungsindex je nach Anteil der einzelnen Bestandteile leicht.",
            lithotherapie = "Unakit wird traditionell mit emotionalem Gleichgewicht und schrittweiser Heilung nach einer seelischen Erschütterung assoziiert."
        ),
        "oeil-de-sainte-lucie" to GemTranslation(
            nom = "Auge der Heiligen Lucia",
            descriptionCourte = "Der spiralförmige Kalkdeckel einer Meeresschnecke, seit der Antike als Amulett getragen.",
            descriptionLongue = "Das Auge der Heiligen Lucia ist das Operculum, der kleine kalkige „Türverschluss“, der die Gehäuseöffnung bestimmter Meeresschnecken der Gattung Turbo verschließt. Sein spiralförmiges braun-cremefarbenes Muster, das an ein Auge erinnert, machte es in zahlreichen mediterranen Kulturen zu einem traditionellen Schutzamulett.",
            particularites = "Es handelt sich nicht um eine Schneckenschale selbst, sondern um das Operculum, die kalkige Platte, die die Öffnung des lebenden Schneckentiers verschließt; sie löst sich nach dem Tod des Tieres von selbst ab.",
            lithotherapie = "Seit der Antike als Anhänger getragen, soll dieses Amulett vor dem bösen Blick schützen und seinem Träger Glück bringen."
        ),
        "jais" to GemTranslation(
            nom = "Gagat",
            descriptionCourte = "Eine matte, tiefschwarze fossile Kohle, Sinnbild der viktorianischen Trauermode.",
            descriptionLongue = "Gagat ist eine kompakte Braunkohle-Varietät, fossiles Holz, das über Jahrmillionen unter hohem Druck versteinerte und zu einem tiefen, samtigen Schwarz poliert wird. Sein geringes Gewicht und seine leichte Bearbeitbarkeit machten ihn zum Sinnbild-Material der viktorianischen Trauerschmuckherstellung, insbesondere rund um Whitby in England.",
            particularites = "Erwärmt sich schnell im Kontakt mit der Haut und kann sich, ähnlich wie Bernstein, durch Reibung elektrostatisch aufladen.",
            lithotherapie = "Gagat wird traditionell mit dem Schutz vor negativen Energien und dem Begleiten von Trauerprozessen assoziiert."
        ),
        "vivianite" to GemTranslation(
            nom = "Vivianit",
            descriptionCourte = "Ein tiefblaues Eisenphosphat, so weich und lichtempfindlich, dass es ein reines Sammlermineral bleibt.",
            descriptionLongue = "Vivianit entsteht durch die Verwitterung eisenhaltiger Minerale in sauerstoffarmen Milieus — Torfmooren, Tonen oder auf der Oberfläche fossiler Knochen und Zähne, wo er zum Beispiel manche sibirischen Mammutstoßzähne blaugrün färbt. Frisch geborgen fast farblos, verdunkelt er sich innerhalb weniger Stunden Lichteinwirkung zu einem tiefen Indigoblau, manchmal fast Schwarz, durch die Oxidation des enthaltenen Eisens. Die schönsten, langgestreckten und wohlgeformten Kristalle stammen heute fast ausschließlich aus der Mine von Anloa in Bolivien.",
            particularites = "Äußerst weich und licht- sowie hitzeempfindlich, wird er praktisch nie für den Schmuck geschliffen: Vor direktem Licht geschützt aufbewahrt, um seine Farbe zu erhalten, bleibt er ein Sammlerstein. Seine vollkommene Spaltbarkeit erzeugt dünne, beinahe biegsame Lamellen.",
            lithotherapie = "In lithotherapeutischen Traditionen wird Vivianit mit Loslassen und innerer Wandlung assoziiert — ein traditioneller Glaube ohne gesicherte wissenschaftliche Grundlage.",
            inclusions = "Das kennzeichnende Merkmal der Art ist kein Einschluss, sondern ein Farbwechsel: frisch freigelegte, fast farblose Kristalle verdunkeln sich innerhalb weniger Stunden Lichteinwirkung zu einem tiefen Blau, während das enthaltene Eisen oxidiert."
        ),
        "grenat-etoile" to GemTranslation(
            nom = "Sterngranat",
            descriptionCourte = "Ein Almandin mit vier oder sechs leuchtenden Strahlen, eine Rarität, die fast ausschließlich in Idaho gefunden wird.",
            descriptionLongue = "Der Sterngranat ist ein Almandin, dessen feine orientierte Einschlüsse (meist Rutil) unter punktförmiger Beleuchtung einen vier- oder, seltener, sechsstrahligen Asterismus erzeugen. In Edelsteinqualität ist er nur an zwei Orten der Welt bekannt: in Idaho, USA, und in einigen Lagerstätten Indiens.",
            particularites = "Idaho ist der einzige Ort der Welt, an dem vierstrahlige Sterngranate gefunden werden; die selteneren sechsstrahligen Sterne stammen aus denselben Lagerstätten.",
            lithotherapie = "Der Sterngranat wird mit innerer Kraft und Orientierung in Momenten der Unsicherheit assoziiert."
        ),
        "opale-peruvienne" to GemTranslation(
            nom = "Peruanischer Opal",
            descriptionCourte = "Ein undurchsichtiger blaugrüner oder rosafarbener Opal ohne Farbenspiel, einzigartig für Peru.",
            descriptionLongue = "Der Peruanische Opal ist ein undurchsichtiger gemeiner Opal in einem an Meerwasser erinnernden Blaugrün oder, seltener, in zartem Rosa – zwei Farbtöne, die auf Kupferspuren zurückzuführen sind. Er wird ausschließlich in den peruanischen Anden abgebaut und für den Schmuckgebrauch zu Cabochons geschliffen.",
            particularites = "Seine Farbe verdankt er Kupferspuren, ein bei Opalen seltenes Färbungsphänomen, da diese in der Tiefe normalerweise farblos sind.",
            lithotherapie = "Der Peruanische Opal wird mit emotionaler Beruhigung und Kommunikation assoziiert, im Einklang mit seinem blaugrünen Farbton."
        ),
        "opale-commune" to GemTranslation(
            nom = "Gemeiner Opal",
            descriptionCourte = "Die am weitesten verbreitete Opalvarietät, milchig und ohne Farbenspiel.",
            descriptionLongue = "Der gemeine Opal, auch Milchopal genannt, macht den Großteil der weltweiten Opalproduktion aus, zeigt jedoch nicht das Farbenspiel, das den Edelopal so wertvoll macht. Weiß, durchscheinend oder gelegentlich gefärbt, wird er zu erschwinglichen Preisen als Cabochon geschliffen.",
            particularites = "Das Fehlen des Farbenspiels unterscheidet den gemeinen Opal vom Edelopal; beide teilen jedoch dieselbe Zusammensetzung.",
            lithotherapie = "Dem gemeinen Opal wird nachgesagt, im Alltag Sanftheit und Beruhigung zu spenden."
        ),
        "opale-noire" to GemTranslation(
            nom = "Schwarzer Opal",
            descriptionCourte = "Das spektakulärste Farbenspiel, auf einem dunklen Untergrund, der es besonders zur Geltung bringt.",
            descriptionLongue = "Der schwarze Opal verdankt seinen Namen seinem dunklen, grauen bis schwarzen Untergrund, auf dem das Farbenspiel mit unvergleichlicher Intensität hervortritt. Er wird fast ausschließlich in Lightning Ridge in New South Wales abgebaut und gilt als der wertvollste aller Opale.",
            particularites = "Der dunkle Untergrund entsteht durch Kohlenstoff- und Eisenoxidspuren zwischen den Silica-Kügelchen, ein Phänomen, das für die Lagerstätte Lightning Ridge charakteristisch ist.",
            lithotherapie = "Der schwarze Opal wird mit innerer Wandlung und Schutz in Zeiten tiefgreifenden Wandels assoziiert."
        ),
        "opale-boulder" to GemTranslation(
            nom = "Boulderopal",
            descriptionCourte = "Ein feiner Opalschleier auf seinem eisenhaltigen braunen Sandsteingestein, das beim Schliff bewusst erhalten bleibt.",
            descriptionLongue = "Der Boulderopal bildet sich in feinen Adern innerhalb eines eisenhaltigen braunen Gesteins (Ironstone) in Queensland. Statt den Opal von seinem – zu dünnen und brüchigen – Muttergestein zu trennen, schleifen die Lapidare den Stein mit dem natürlichen braunen Untergrund, der das Farbenspiel zur Geltung bringt.",
            particularites = "Im Gegensatz zu anderen Opalen enthält er bewusst sein Wirtsgestein, was ihn schlagfester macht als einen reinen Opal.",
            lithotherapie = "Der Boulderopal wird mit Erdung und Stabilität assoziiert, im Einklang mit dem Gestein, das ihn trägt."
        ),
        "opale-ethiopie" to GemTranslation(
            nom = "Äthiopischer Opal",
            descriptionCourte = "Ein Opal mit lebhaftem Farbenspiel auf honigfarbenem Untergrund, jedoch hydrophan und daher wasserempfindlich.",
            descriptionLongue = "In den 2010er-Jahren in der Region Wollo entdeckt, hat der Äthiopische Opal den Markt mit seinem besonders lebhaften Farbenspiel auf honigfarbenem bis farblosem, durchscheinendem Untergrund revolutioniert. Seine hydrophane Natur – er saugt Wasser wie ein Schwamm auf – macht ihn jedoch instabil, wenn er ins Wasser getaucht oder zu starker Feuchtigkeit ausgesetzt wird.",
            particularites = "Hydrophane Natur: kann bis zu 20% seines Volumens an Wasser aufnehmen, beim Trocknen rissig werden und bei Feuchtigkeitskontakt vorübergehend seine Transparenz verändern.",
            inclusions = "Hydrophane (poröse) Beschaffenheit, die Wasser aufnehmen und die Transparenz vorübergehend verändern kann; innere Struktur aus Kieselsäurekügelchen, verantwortlich für das Farbenspiel.",
